// Hauptfunktion: Zone Availability basierend auf Mode berechnen
export const getZoneAvailability = (mode: RetroRetroMode): ZoneAvailability => {
  const config = GAMESZONE_CONFIG[mode];
  
  // Verfügbare Games pro Zone berechnen
  const availableSingleplayerGames = SINGLEPLAYER_GAMES.filter(game => 
    checkGameRequirements(game, mode)
  );
  
  const availableMultiplayerGames = MULTIPLAYER_GAMES.filter(game => 
    config.enableMultiplayer && checkGameRequirements(game, mode)
  );
  
  const availableArcadeGames = ARCADE_GAMES.filter(game => 
    config.enableArcade && checkGameRequirements(game, mode)
  );
  
  return {
    singleplayer: {
      enabled: config.enableSingleplayer,
      games: availableSingleplayerGames.length
    },
    multiplayer: {
      enabled: config.enableMultiplayer,
      games: availableMultiplayerGames.length
    },
    arcade: {
      enabled: config.enableArcade,
      games: availableArcadeGames.length
    }
  };
};

// Game Requirements Checker
const checkGameRequirements = (game: GameDefinition, mode: RetroRetroMode): boolean => {
  if (!game.requirements || game.requirements.length === 0) {
    return true; // Keine Requirements = immer verfügbar
  }
  
  return game.requirements.every(requirement => {
    switch (requirement) {
      case 'level01':
        return mode !== RETRO_MODES.DEMO;
      case 'level02':
        return ([RETRO_MODES.LEVEL02, RETRO_MODES.VIP, RETRO_MODES.PREMIUM, RETRO_MODES.ADMIN] as RetroRetroMode[]).includes(mode);
      case 'vip':
        return ([RETRO_MODES.VIP, RETRO_MODES.PREMIUM, RETRO_MODES.ADMIN] as RetroRetroMode[]).includes(mode);
      case 'premium':
        return ([RETRO_MODES.PREMIUM, RETRO_MODES.ADMIN] as RetroRetroMode[]).includes(mode);
      case 'not-demo':
        return mode !== RETRO_MODES.DEMO;
      default:
        return false;
    }
  });
};