// NEW: Utility function to create dynamic neon pulse
export const createNeonPulse = (color: string, intensity: 'subtle' | 'medium' | 'strong' | 'intense' = 'medium') => {
  const intensityMap = {
    subtle: { start: '5px 8px', end: '3px 6px' },
    medium: { start: '8px 15px 25px', end: '5px 10px 15px' },
    strong: { start: '10px 20px 30px', end: '5px 10px 15px' },
    intense: { start: '15px 30px 45px 60px', end: '8px 15px 25px 35px' }
  };
  
  const { start, end } = intensityMap[intensity];
  
  return keyframes`
    0% {
      text-shadow: 
        0 0 ${start.split(' ').map(val => `${val} ${color}`).join(', ')};
    }
    100% {
      text-shadow: 
        0 0 ${end.split(' ').map(val => `${val} ${color}`).join(', ')};
    }
  `;
};

