// ===================================
// UTILITY FUNCTIONS
// ===================================

// NEW: Helper function to generate box-shadow with specific color
export const createBoxShadow = (intensity: keyof typeof retroTheme.shadows.box, color: string): string => {
  const template = retroTheme.shadows.box[intensity];
  // RGB-Werte aus Hex-Color extrahieren
  const hex = color.replace('#', '');
  const r = parseInt(hex.substr(0, 2), 16);
  const g = parseInt(hex.substr(2, 2), 16);
  const b = parseInt(hex.substr(4, 2), 16);
  
  return template.replace(/COLOR_PLACEHOLDER/g, `${r}, ${g}, ${b}`);
};

// NEW: Helper function to get status color
export const getStatusColor = (type: keyof typeof retroTheme.colors.status): string => {
  return retroTheme.colors.status[type];
};

// NEW: Helper function to get button color
export const getButtonColor = (variant: keyof typeof retroTheme.colors.button): string => {
  return retroTheme.colors.button[variant];
};

// NEW: Helper function to create responsive styles
export const createResponsiveStyle = (mobileStyle: string, tabletStyle?: string, desktopStyle?: string) => `
  ${mobileStyle}
  
  @media (min-width: ${retroTheme.breakpoints.mobile}) {
    ${tabletStyle || mobileStyle}
  }
  
  @media (min-width: ${retroTheme.breakpoints.desktop}) {
    ${desktopStyle || tabletStyle || mobileStyle}
  }
`;

// Export everything
export { retroTheme as default };