import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import styled, { keyframes } from 'styled-components';

// Retro Animations
const neonPulse = keyframes`
  0% {
    text-shadow: 
      0 0 15px #ff00ff,
      0 0 30px #ff00ff,
      0 0 45px #ff00ff,
      0 0 60px #ff00ff;
  }
  100% {
    text-shadow: 
      0 0 8px #ff00ff,
      0 0 15px #ff00ff,
      0 0 25px #ff00ff,
      0 0 35px #ff00ff;
  }
`;

const neonPulseGreen = keyframes`
  0% {
    text-shadow: 
      0 0 10px #00ff00,
      0 0 20px #00ff00,
      0 0 30px #00ff00;
  }
  100% {
    text-shadow: 
      0 0 5px #00ff00,
      0 0 10px #00ff00,
      0 0 15px #00ff00;
  }
`;

const boxGlow = keyframes`
  0% {
    box-shadow: 
      0 0 20px rgba(255, 0, 255, 0.5),
      0 0 40px rgba(255, 0, 255, 0.3);
    border-color: #ff00ff;
  }
  100% {
    box-shadow: 
      0 0 30px rgba(255, 0, 255, 0.8),
      0 0 60px rgba(255, 0, 255, 0.4);
    border-color: #ff00ff;
  }
`;

const softNeonFlicker = keyframes`
  0%, 100% {
    text-shadow: 
      0 0 8px #ff00ff,
      0 0 15px #ff00ff,
      0 0 25px #ff00ff;
  }
  50% {
    text-shadow: 
      0 0 5px #ff00ff,
      0 0 10px #ff00ff,
      0 0 18px #ff00ff;
  }
`;

// Styled Components
const Container = styled.div`
  font-family: 'Courier New', monospace;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
  color: #ffffff;
  min-height: 100vh;
  margin: 0;
  padding: 0;
  box-sizing: border-box;
`;

// HEADER WIE RETROARCADEHOME - für korrektes Spacing
const Header = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 2rem;
`;

// TITEL-ALIGNMENT FIX - EXAKT wie RetroArcadeHome
const TitleContainer = styled.div`
  text-align: center;
  margin: 3rem 0;
`;

// REGISTER Titel - GESPERRT wie LoginPage
const Title = styled.h1`
  font-size: 6rem;
  font-weight: bold;
  color: #ff00ff;
  text-transform: uppercase;
  letter-spacing: 0.8rem;  // ← Gesperrt wie LOGIN Titel
  margin: 0;
  text-align: center;
  text-shadow: 
    0 0 15px #ff00ff,
    0 0 30px #ff00ff,
    0 0 45px #ff00ff,
    0 0 60px #ff00ff;
  animation: ${neonPulse} 2s infinite alternate;

  @media (max-width: 768px) {
    font-size: 3.5rem;
    letter-spacing: 0.5rem;
  }
`;

// NEON NAVIGATION BUTTON - ANGEPASST AN REGISTER TITEL-FARBE
const NeonNavButton = styled.button`
  background: transparent;
  border: 2px solid #ff00ff;  // ← REGISTER Titel-Farbe
  color: #ff00ff;             // ← REGISTER Titel-Farbe
  padding: 0.8rem 2rem;
  border-radius: 8px;
  font-size: 1.2rem;
  font-weight: bold;
  font-family: 'Courier New', monospace;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  cursor: pointer;
  transition: all 0.3s ease;
  position: relative;
  
  /* Neon-Effekt in REGISTER-Farbe */
  text-shadow: 
    0 0 8px #ff00ff,
    0 0 15px #ff00ff;
  box-shadow: 
    0 0 10px rgba(255, 0, 255, 0.5),
    inset 0 0 10px rgba(255, 0, 255, 0.1);
  
  /* Animation in REGISTER-Farbe */
  animation: ${neonPulse} 8s ease-in-out infinite;
  
  /* Zusätzlicher Glow-Effekt */
  &::before {
    content: '';
    position: absolute;
    top: -2px;
    left: -2px;
    right: -2px;
    bottom: -2px;
    background: linear-gradient(45deg, #ff00ff, #aa00aa, #ff00ff);
    border-radius: 8px;
    z-index: -1;
    opacity: 0.3;
    animation: ${softNeonFlicker} 4s linear infinite;
  }

  &:hover {
    transform: scale(1.05);
    border-color: #aa00aa;
    color: #aa00aa;
    text-shadow: 
      0 0 8px #aa00aa,
      0 0 15px #aa00aa,
      0 0 25px #aa00aa;
    box-shadow: 
      0 0 20px rgba(170, 0, 170, 0.8),
      inset 0 0 20px rgba(170, 0, 170, 0.2);
  }

  &:active {
    transform: scale(0.98);
  }
`;

// NAVIGATION-CONTAINER FIX - VERTIKALE MITTE zwischen Titel und Register-Container
const NavigationContainer = styled.div`
  display: flex;
  justify-content: center;
  gap: 1.5rem;
  margin: 1.5rem 0 3rem 0;
  
  @media (max-width: 768px) {
    flex-direction: column;
    align-items: center;
    gap: 1rem;
  }
`;

const ContentArea = styled.div`
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 1rem;
  gap: 2rem;

  @media (max-width: 768px) {
    flex-direction: column;
    align-items: center;
  }
`;

const RegisterContainer = styled.div`
  background: rgba(0, 0, 0, 0.9);
  border: 4px solid #ff00ff;
  border-radius: 15px;
  padding: 3rem;
  width: 100%;
  max-width: 500px;
  animation: ${boxGlow} 3s infinite alternate;

  @media (max-width: 768px) {
    width: 90%;
    max-width: 400px;
    padding: 2rem;
  }
`;

const Form = styled.form`
  display: flex;
  flex-direction: column;
  gap: 1.2rem;
`;

const InputGroup = styled.div`
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
`;

const Label = styled.label`
  color: #ff00ff;
  font-weight: bold;
  text-transform: uppercase;
  font-size: 0.9rem;
  text-shadow: 0 0 5px #ff00ff;
  letter-spacing: 0.1rem;
`;

const Input = styled.input`
  width: 100%;
  padding: 0.8rem;
  background: rgba(0, 0, 0, 0.7);
  border: 2px solid #ff00ff;
  border-radius: 8px;
  color: #ffffff;
  font-family: 'Courier New', monospace;
  font-size: 1rem;
  box-sizing: border-box;
  text-shadow: 0 0 5px #ffffff;
  transition: all 0.3s ease;

  &::placeholder {
    color: rgba(255, 255, 255, 0.5);
  }

  &:focus {
    outline: none;
    border-color: #ffff00;
    box-shadow: 
      0 0 10px rgba(255, 255, 0, 0.5),
      inset 0 0 10px rgba(255, 255, 0, 0.1);
    text-shadow: 0 0 8px #ffffff;
  }
  
  &:disabled {
    opacity: 0.6;
    cursor: not-allowed;
  }
`;

const SubmitButton = styled.button`
  width: 100%;
  padding: 1rem;
  margin-top: 1rem;
  background: rgba(0, 255, 0, 0.2);
  border: 2px solid #00ff00;
  border-radius: 8px;
  color: #00ff00;
  font-family: 'Courier New', monospace;
  font-size: 1.1rem;
  font-weight: bold;
  text-transform: uppercase;
  cursor: pointer;
  transition: all 0.3s ease;
  text-shadow: 0 0 5px #00ff00;
  box-shadow: 0 0 8px rgba(0, 255, 0, 0.3);
  animation: ${neonPulseGreen} 2s infinite alternate;
  
  &:hover:not(:disabled) {
    background: rgba(0, 255, 0, 0.3);
    box-shadow: 
      0 0 15px rgba(0, 255, 0, 0.6),
      inset 0 0 15px rgba(0, 255, 0, 0.2);
    text-shadow: 0 0 8px #00ff00;
    transform: scale(1.02);
  }

  &:disabled {
    opacity: 0.6;
    cursor: not-allowed;
    transform: none;
    animation: none;
  }
`;

const LinkText = styled.p`
  text-align: center;
  margin-top: 1.5rem;
  color: #ffffff;
  
  a {
    color: #ff00ff;
    text-decoration: none;
    font-weight: bold;
    cursor: pointer;
    text-shadow: 0 0 5px #ff00ff;
    
    &:hover {
      text-shadow: 0 0 8px #ff00ff, 0 0 15px #ff00ff;
    }
  }
`;

const ErrorMessage = styled.div`
  color: #ff0000;
  background: rgba(255, 0, 0, 0.1);
  border: 2px solid #ff0000;
  border-radius: 8px;
  padding: 0.8rem;
  text-align: center;
  margin-bottom: 1rem;
  text-shadow: 0 0 5px #ff0000;
  box-shadow: 0 0 10px rgba(255, 0, 0, 0.3);
`;

const SuccessMessage = styled.div`
  color: #00ff00;
  background: rgba(0, 255, 0, 0.1);
  border: 2px solid #00ff00;
  border-radius: 8px;
  padding: 0.8rem;
  text-align: center;
  margin-bottom: 1rem;
  text-shadow: 0 0 5px #00ff00;
  box-shadow: 0 0 10px rgba(0, 255, 0, 0.3);
`;

// RegisterPage Component
const RegisterPage: React.FC = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    password: '',
    confirmPassword: ''
  });
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
    // Clear messages when user starts typing
    if (error) setError('');
    if (success) setSuccess('');
  };

  const validateForm = () => {
    if (!formData.username || !formData.email || !formData.password || !formData.confirmPassword) {
      return 'All fields are required!';
    }
    
    if (formData.username.length < 3) {
      return 'Username must be at least 3 characters!';
    }
    
    if (formData.password.length < 6) {
      return 'Password must be at least 6 characters!';
    }
    
    if (formData.password !== formData.confirmPassword) {
      return 'Passwords do not match!';
    }
    
    // Basic email validation
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(formData.email)) {
      return 'Please enter a valid email address!';
    }
    
    return null;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');
    setSuccess('');

    const validationError = validateForm();
    if (validationError) {
      setError(validationError);
      setIsLoading(false);
      return;
    }

    try {
      // TODO: Implement actual registration logic
      console.log('Registration attempt:', { 
        username: formData.username, 
        email: formData.email 
      });
      
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1500));
      
      // For now, always succeed
      setSuccess('Registration successful! Redirecting to profile...');
      console.log('Registration successful');
      
      // Redirect to profile after success
      setTimeout(() => {
        navigate('/profile');
      }, 2000);
      
    } catch (err) {
      console.error('Registration failed:', err);
      setError('Registration failed! Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleProfileClick = () => {
    console.log('Navigating to profile');
    navigate('/profile');
  };

  const handleGamesClick = () => {
    console.log('Navigating to games');
    navigate('/games');
  };

  const handleLoginClick = () => {
    console.log('Navigating to login');
    navigate('/login');
  };

  return (
    <Container>
      {/* Header wie RetroArcadeHome - für korrektes Spacing */}
      <Header>
        <div></div>
      </Header>

      {/* REGISTER Titel - jetzt exakt wie RetroArcadeHome */}
      <TitleContainer>
        <Title>REGISTER</Title>
      </TitleContainer>

      {/* Navigation mit PROFILE und GAMES Buttons */}
      <NavigationContainer>
        <NeonNavButton onClick={handleProfileClick}>
          PROFILE
        </NeonNavButton>
        <NeonNavButton onClick={handleGamesClick}>
          GAMES
        </NeonNavButton>
      </NavigationContainer>

      <ContentArea>
        <RegisterContainer>
          {error && <ErrorMessage>{error}</ErrorMessage>}
          {success && <SuccessMessage>{success}</SuccessMessage>}
          
          <Form onSubmit={handleSubmit}>
            <InputGroup>
              <Label htmlFor="username">Username</Label>
              <Input
                type="text"
                id="username"
                name="username"
                placeholder="Choose a cool username"
                value={formData.username}
                onChange={handleInputChange}
                disabled={isLoading}
              />
            </InputGroup>

            <InputGroup>
              <Label htmlFor="email">Email Address</Label>
              <Input
                type="email"
                id="email"
                name="email"
                placeholder="player@retro.game"
                value={formData.email}
                onChange={handleInputChange}
                disabled={isLoading}
              />
            </InputGroup>

            <InputGroup>
              <Label htmlFor="password">Password</Label>
              <Input
                type="password"
                id="password"
                name="password"
                placeholder="Create a strong password"
                value={formData.password}
                onChange={handleInputChange}
                disabled={isLoading}
              />
            </InputGroup>

            <InputGroup>
              <Label htmlFor="confirmPassword">Confirm Password</Label>
              <Input
                type="password"
                id="confirmPassword"
                name="confirmPassword"
                placeholder="Confirm your password"
                value={formData.confirmPassword}
                onChange={handleInputChange}
                disabled={isLoading}
              />
            </InputGroup>

            <SubmitButton type="submit" disabled={isLoading}>
              {isLoading ? 'CREATING ACCOUNT...' : 'REGISTER'}
            </SubmitButton>
          </Form>

          <LinkText>
            Already have an account?{' '}
            <a onClick={handleLoginClick}>
              Login here
            </a>
          </LinkText>
        </RegisterContainer>
      </ContentArea>
    </Container>
  );
};

export default RegisterPage;