// frontend/src/managers/SocketManager/SocketManager.ts
// Vollständige Integration von websocketIntegration.ts + SocketService.js

import { io, Socket } from 'socket.io-client';
import { SocketEvents } from './websocketEvents';
import { SocketTypes } from './types';

class SocketManager {
  private static instance: SocketManager | null = null;
  
  // === CORE STATE (from websocketIntegration.ts) ===
  private socket: Socket | null = null;
  private authorityLevel: string = 'DEMO';
  private currentUser: string = 'anonymous';
  private isConnected: boolean = false;
  private reconnectAttempts: number = 0;
  private maxReconnectAttempts: number = 5;
  
  // === CONNECTION STATE (from SocketService.js) ===
  private connectionStates = {
    DISCONNECTED: 'disconnected',
    CONNECTING: 'connecting',
    CONNECTED: 'connected', 
    AUTHENTICATED: 'authenticated',
    ERROR: 'error'
  };
  private currentState: string = this.connectionStates.DISCONNECTED;
  
  // === EVENT MANAGEMENT ===
  private eventListeners: Map<string, Set<Function>> = new Map();
  
  // === CONFIGURATION ===
  private serverUrl: string;
  private socketConfig = {
    transports: ['websocket', 'polling'],
    timeout: 20000,
    forceNew: true,
    reconnection: true,
    reconnectionDelay: 1000,
    reconnectionAttempts: 5
  };

  private constructor() {
    this.serverUrl = process.env.REACT_APP_SOCKET_URL || 'http://localhost:3001';
    console.log('🎮 RETRORETRO Socket.IO Integration initializing...');
  }

  // === SINGLETON ===
  public static getInstance(): SocketManager {
    if (!SocketManager.instance) {
      SocketManager.instance = new SocketManager();
    }
    return SocketManager.instance;
  }

  // === MAIN INITIALIZATION (from websocketIntegration.ts) ===
  async initializeAfterLogin(authorityData?: { level: string, user: string }): Promise<{ success: boolean; error?: string }> {
    try {
      console.log('🔐 Initializing Socket.IO after successful login...');
      
      // 1. Set Authority Data (FIXED: from parameter, not HTTP API)
      if (authorityData) {
        this.authorityLevel = authorityData.level;
        this.currentUser = authorityData.user;
        console.log(`✅ Authority from parameter: ${this.authorityLevel} (${this.currentUser})`);
      } else {
        // Fallback: Default for temporary test
        this.authorityLevel = 'DEMO';
        this.currentUser = 'anonymous';
        console.log('⚠️ No authority data provided, using DEMO/anonymous');
      }

      // 2. Connect Socket
      const result = await this.connect();
      if (!result.success) {
        throw new Error(result.error || 'Socket connection failed');
      }

      // 3. Send Authority Handshake
      await this.sendAuthorityHandshake();

      console.log('🚀 Socket.IO Integration completed successfully!');
      return { success: true };

    } catch (error) {
      console.error('❌ Socket.IO Integration failed:', error);
      return { success: false, error: 'Connection failed' };
    }
  }

  // === CONNECTION MANAGEMENT ===
  async connect(): Promise<{ success: boolean; error?: string }> {
    try {
      // Prüfe ob bereits verbunden
      if (this.isConnected && this.socket?.connected) {
        console.log('[SocketManager] Already connected');
        return { success: true };
      }
  
      // Prüfe ob bereits eine Verbindung läuft
      if (this.currentState === this.connectionStates.CONNECTING) {
        console.log('[SocketManager] ⚠️ Connection already in progress - waiting...');
        // Warte bis Verbindung fertig ist
        return new Promise((resolve) => {
          const checkInterval = setInterval(() => {
            if (this.currentState === this.connectionStates.CONNECTED) {
              clearInterval(checkInterval);
              resolve({ success: true });
            } else if (this.currentState === this.connectionStates.ERROR) {
              clearInterval(checkInterval);
              resolve({ success: false, error: 'Connection failed' });
            }
          }, 100);
        });
      }

      console.log(`[SocketManager] Connecting to ${this.serverUrl}...`);
      this.currentState = this.connectionStates.CONNECTING;

      // Create socket connection
      this.socket = io(this.serverUrl, this.socketConfig);

      // Setup event listeners
      this.setupSocketEventListeners();

      // Wait for connection
      return new Promise((resolve, reject) => {
        const connectionTimeout = setTimeout(() => {
          reject(new Error('Connection timeout'));
        }, this.socketConfig.timeout);

        this.socket!.on('connect', () => {
          clearTimeout(connectionTimeout);
          console.log('✅ Socket connected successfully');
          this.isConnected = true;
          this.currentState = this.connectionStates.CONNECTED;
          this.reconnectAttempts = 0;
          
          this.emitToListeners('connect', { 
            socketId: this.socket!.id,
            timestamp: new Date().toISOString() 
          });
          resolve({ success: true });
        });

        this.socket!.on('connect_error', (error) => {
          clearTimeout(connectionTimeout);
          console.error('❌ Socket connection failed:', error);
          this.currentState = this.connectionStates.ERROR;
          this.emitToListeners('connect_error', error);
          reject(error);
        });
      });

    } catch (error) {
      console.error('[SocketManager] Connection error:', error);
      this.currentState = this.connectionStates.ERROR;
      return { success: false, error: 'Connection failed' };
    }
  }

  disconnect(): void {
    console.log('[SocketManager] Disconnecting socket...');
    
    if (this.socket) {
      this.socket.disconnect();
      this.socket = null;
    }
    
    this.isConnected = false;
    this.currentState = this.connectionStates.DISCONNECTED;
    this.emitToListeners('disconnect', { 
      timestamp: new Date().toISOString() 
    });
  }

  // === PUBLIC SOCKET GETTER ===
  public getSocket(): Socket | null {
    return this.socket;
  }

  // === AUTHORITY MANAGEMENT (from websocketIntegration.ts) ===
  async sendAuthorityHandshake(): Promise<void> {
    if (!this.socket || !this.isConnected) {
      throw new Error('Socket not connected');
    }

    console.log('[SocketManager] Sending authority handshake...');
    
    const handshakeData = {
      authority: this.authorityLevel,
      user: this.currentUser,
      timestamp: new Date().toISOString(),
      clientVersion: '1.0.0'
    };

    this.socket.emit('authority-handshake', handshakeData);
    
    // Wait for confirmation
    return new Promise((resolve, reject) => {
      const timeout = setTimeout(() => {
        reject(new Error('Authority handshake timeout'));
      }, 10000);

      const onConfirmed = (data: any) => {
        clearTimeout(timeout);
        if (this.socket) {
          this.socket.off('authority-confirmed', onConfirmed);
          this.socket.off('authority-failed', onFailed);
        }
        
        console.log('✅ Authority confirmed:', data);
        this.currentState = this.connectionStates.AUTHENTICATED;
        resolve();
      };

      const onFailed = (error: any) => {
        clearTimeout(timeout);
        if (this.socket) {
          this.socket.off('authority-confirmed', onConfirmed);
          this.socket.off('authority-failed', onFailed);
        }
        
        console.error('❌ Authority failed:', error);
        reject(new Error(`Authority verification failed: ${error.message}`));
      };

      if (!this.socket) {
        reject(new Error('Socket not connected'));
        return;
      }

      this.socket.on('authority-confirmed', onConfirmed);
      this.socket.on('authority-failed', onFailed);
    });
  }

  setAuthorityData(level: string, user: string): void {
    this.authorityLevel = level;
    this.currentUser = user;
    console.log(`[SocketManager] Authority updated: ${level} (${user})`);
  }

  // === EVENT SYSTEM ===
  on(event: string, callback: Function): void {
    // Add to internal listeners
    if (!this.eventListeners.has(event)) {
      this.eventListeners.set(event, new Set());
    }
    this.eventListeners.get(event)!.add(callback);

    // Forward to socket if connected
    if (this.socket) {
      this.socket.on(event, callback as any);
    }
  }

  off(event: string, callback?: Function): void {
    if (callback) {
      this.eventListeners.get(event)?.delete(callback);
      if (this.socket) {
        this.socket.off(event, callback as any);
      }
    } else {
      this.eventListeners.delete(event);
      if (this.socket) {
        this.socket.off(event);
      }
    }
  }

  emit(event: string, data?: any): void {
    if (this.socket && this.isConnected) {
      this.socket.emit(event, data);
    } else {
      console.warn(`[SocketManager] Cannot emit ${event}: Not connected`);
    }
  }

  // === SESSIONMANAGER COMPATIBILITY METHODS ===
  async connectSocket(authToken: string): Promise<{ success: boolean; error?: string }> {
    console.log('[SocketManager] SessionManager compatibility: connectSocket()');
    
    try {
      // Parse authority from token if needed
      const authorityData = this.parseAuthToken(authToken);
      return await this.initializeAfterLogin(authorityData);
    } catch (error) {
      console.error('[SocketManager] connectSocket failed:', error);
      this.emitToListeners('socketError', error instanceof Error ? error.message : 'Socket connection failed');
      return { success: false, error: 'Connection failed' };
    }
  }

  disconnectSocket(): void {
    console.log('[SocketManager] SessionManager compatibility: disconnectSocket()');
    this.disconnect();
    this.emitToListeners('socketDisconnected', undefined);
  }

  // Test methods (from SocketService.js)
  sendTestPing(): void {
    if (this.isConnected) {
      this.emit('ping', { 
        timestamp: Date.now(), 
        user: this.currentUser 
      });
    }
  }

  sendTestMessage(message: string): void {
    if (this.isConnected) {
      this.emit('test-message', { 
        message, 
        user: this.currentUser,
        timestamp: Date.now()
      });
    }
  }

  requestServerInfo(): void {
    if (this.isConnected) {
      this.emit('get-server-info');
    }
  }

  // === STATE GETTERS ===
  getIsConnected(): boolean {
    return this.isConnected && this.socket?.connected === true;
  }

  isSocketReady(): boolean {
    return this.currentState === this.connectionStates.AUTHENTICATED;
  }

  getCurrentState(): string {
    return this.currentState;
  }

  getSocketId(): string | undefined {
    return this.socket?.id;
  }

  getAuthorityStatus(): SocketTypes.AuthorityStatus {
    return {
      connected: this.isConnected,
      authority: this.authorityLevel,
      socketReady: this.isSocketReady(),
      user: this.currentUser,
      lastHeartbeat: new Date().toISOString()
    };
  }

  getConnectionInfo(): SocketTypes.ConnectionStatus {
    return {
      connected: this.isConnected,
      authority: this.authorityLevel,
      socketReady: this.isSocketReady(),
      user: this.currentUser,
      lastHeartbeat: new Date().toISOString(),
      state: this.currentState
    };
  }

  // === PRIVATE METHODS ===
  private setupSocketEventListeners(): void {
    if (!this.socket) return;

    console.log('[SocketManager] Setting up socket event listeners...');

    // Connection Events
    this.socket.on('disconnect', (reason) => {
      console.log('[SocketManager] Disconnected:', reason);
      this.isConnected = false;
      this.currentState = this.connectionStates.DISCONNECTED;
      
      this.emitToListeners('disconnect', { reason });
      this.emitToListeners('socketDisconnected', { reason });

      // Auto-reconnect logic
      if (reason === 'io server disconnect' && this.reconnectAttempts < this.maxReconnectAttempts) {
        this.handleReconnect();
      }
    });

    // Authority Events
    this.socket.on('authority-confirmed', (data) => {
      console.log('[SocketManager] Authority confirmed:', data);
      this.currentState = this.connectionStates.AUTHENTICATED;
      this.emitToListeners('authority-confirmed', data);
      this.emitToListeners('socketAuthenticated', data);
    });

    this.socket.on('authority-failed', (data) => {
      console.warn('[SocketManager] Authority verification failed:', data);
      this.emitToListeners('authority-failed', data);
    });

    // Session Events (SessionManager compatibility)
    this.socket.on('playerCount', (count) => {
      this.emitToListeners('playerCount', count);
    });

    this.socket.on('userOnline', (data) => {
      this.emitToListeners('userOnline', data);
    });

    this.socket.on('userOffline', (data) => {
      this.emitToListeners('userOffline', data);
    });

    this.socket.on('userLoggedIn', (data) => {
      this.emitToListeners('userLoggedIn', data);
    });

    this.socket.on('userLoggedOut', (data) => {
      this.emitToListeners('userLoggedOut', data);
    });

    // Test Events
    this.socket.on('testUserLogin', (data) => {
      this.emitToListeners('testUserLogin', data);
    });

    this.socket.on('testUserLogout', (data) => {
      this.emitToListeners('testUserLogout', data);
    });

    // Error Handling
    this.socket.on('error', (error) => {
      console.error('[SocketManager] Socket error:', error);
      this.emitToListeners('error', error);
      this.emitToListeners('socketError', error);
    });

    // Apply stored event listeners
    this.applyStoredListeners();
  }

  private applyStoredListeners(): void {
    this.eventListeners.forEach((callbacks, event) => {
      callbacks.forEach((callback) => {
        if (this.socket && !['connect', 'disconnect', 'error'].includes(event)) {
          this.socket.on(event, callback as any);
        }
      });
    });
  }

  private emitToListeners(event: string, data: any): void {
    const listeners = this.eventListeners.get(event);
    if (listeners) {
      listeners.forEach((callback) => {
        try {
          callback(data);
        } catch (error) {
          console.error(`[SocketManager] Error in event listener for ${event}:`, error);
        }
      });
    }
  }

  private handleReconnect(): void {
    this.reconnectAttempts++;
    const delay = Math.min(1000 * Math.pow(2, this.reconnectAttempts), 10000);
    
    console.log(`[SocketManager] Reconnecting in ${delay}ms (attempt ${this.reconnectAttempts})`);
    
    setTimeout(() => {
      this.connect();
    }, delay);
  }

  private parseAuthToken(authToken: string): { level: string, user: string } | undefined {
    try {
      // Simple token parsing - adjust based on your token format
      const decoded = JSON.parse(atob(authToken.split('.')[1] || ''));
      return {
        level: decoded.authority || 'USER',
        user: decoded.username || 'unknown'
      };
    } catch (error) {
      console.warn('[SocketManager] Could not parse auth token:', error);
      return undefined;
    }
  }

  // === CLEANUP ===
  destroy(): void {
    console.log('[SocketManager] Destroying instance...');
    this.disconnect();
    this.eventListeners.clear();
    SocketManager.instance = null;
  }
}

export default SocketManager;