/**
 * usePayment Hook - Angepasst für user-spezifische PaymentManager
 * Path: frontend/src/managers/PaymentManager/hooks/usePayment.ts
 * 
 * React Hook für user-spezifische PaymentManager-Instanzen
 * Jeder User bekommt seine eigene PaymentManager-Instanz
 *
 * PaymentManager.ts muss noch einige fehlende Methoden implementieren (createSubscription, etc.)
 * Alte Hook-Aufrufe in Components müssen angepasst werden
 */

import { useState, useEffect, useCallback, useMemo } from 'react';
import PaymentManager from '../PaymentManager';
import type {
  PaymentProduct,
  PaymentConfirmation,
  BillingInfo,
  PaymentHistoryEntry,
  Subscription,
  PaymentMethod,
  ApiResponse,
  PaymentTier,
  PaymentTierConfig,
  TierUpgrade
} from '../PaymentManager';

// Hook state interface - vereinfacht für user-spezifische Manager
interface PaymentState {
  loading: boolean;
  error: string | null;
  products: PaymentProduct[];
  currentBilling: BillingInfo | null;
  paymentHistory: PaymentHistoryEntry[];
  currentTier: PaymentTier;
  availableTiers: PaymentTierConfig[];
}

// Hook return type - angepasst für user-spezifische API
interface UsePaymentReturn {
  // Core payment functions - userId nicht mehr nötig (automatisch verfügbar)
  processPayment: (amount: number, planType: string, planId: string) => Promise<PaymentConfirmation>;
  processTestPayment: (planType: string) => Promise<PaymentConfirmation>;
  fetchUserBilling: () => Promise<ApiResponse<BillingInfo>>;
  fetchPaymentHistory: (page?: number, limit?: number) => Promise<ApiResponse<PaymentHistoryEntry[]>>;

  // Tier Management - vereinfacht
  currentTier: PaymentTier;
  availableTiers: PaymentTierConfig[];
  upgradeTier: (targetTier: PaymentTier, billingCycle?: 'monthly' | 'yearly') => Promise<ApiResponse<PaymentConfirmation>>;
  downgradeTier: (targetTier: PaymentTier) => Promise<ApiResponse<boolean>>;
  canAccessFeature: (feature: keyof PaymentTierConfig['features']) => boolean;
  getTierConfig: (tier: PaymentTier) => PaymentTierConfig;
  getUpgradeRecommendation: () => TierUpgrade | null;

  // State
  loading: boolean;
  error: string | null;
  products: PaymentProduct[];
  currentBilling: BillingInfo | null;
  paymentHistory: PaymentHistoryEntry[];

  // Helper functions
  clearError: () => void;
  loadProducts: () => Promise<void>;
  getProductById: (productId: string) => PaymentProduct | undefined;
  isSubscriptionActive: () => boolean;
  getSubscriptionPlan: () => string;

  // Config
  isDemoMode: boolean;
  userId: string; // NEU: User-ID verfügbar machen
}

/**
 * HINWEIS: User-spezifischer usePayment Hook
 * 
 * Dieser Hook erstellt für jeden User eine eigene PaymentManager-Instanz.
 * Vorteile:
 * - Isolierte Payment-Stati pro User
 * - Keine geteilten Caches zwischen Usern  
 * - Einfachere API (userId automatisch verfügbar)
 * - Bessere Testbarkeit verschiedener User-Szenarien
 */
export const usePayment = (userId: string): UsePaymentReturn => {
  if (!userId) {
    throw new Error('usePayment requires a valid userId');
  }

  // User-spezifische PaymentManager-Instanz (nicht Singleton)
  const paymentManager = useMemo(() => {
    return new PaymentManager(userId);
  }, [userId]);
  
  // State management
  const [state, setState] = useState<PaymentState>({
    loading: false,
    error: null,
    products: [],
    currentBilling: null,
    paymentHistory: [],
    currentTier: 'free',
    availableTiers: paymentManager.getAllTiers()
  });

  // Initialize
  useEffect(() => {
    loadProducts();
    loadCurrentTier();
    
    // Event listeners
    const handlePaymentSuccess = (data: PaymentConfirmation) => {
      console.log('Payment successful:', data);
      setState(prev => ({ ...prev, loading: false }));
      // Refresh tier after successful payment
      loadCurrentTier();
    };

    const handlePaymentError = (error: string) => {
      console.error('Payment error:', error);
      setState(prev => ({ ...prev, error, loading: false }));
    };

    const handleTierUpgraded = (data: { userId: string; toTier: PaymentTier }) => {
      if (data.userId === userId) {
        console.log('Tier upgraded to:', data.toTier);
        setState(prev => ({ ...prev, currentTier: data.toTier }));
      }
    };

    const handleTierDowngraded = (data: { userId: string; toTier: PaymentTier }) => {
      if (data.userId === userId) {
        console.log('Tier downgraded to:', data.toTier);
        setState(prev => ({ ...prev, currentTier: data.toTier }));
      }
    };

    paymentManager.on('paymentSuccess', handlePaymentSuccess);
    paymentManager.on('paymentError', handlePaymentError);
    paymentManager.on('tierUpgraded', handleTierUpgraded);
    paymentManager.on('tierDowngraded', handleTierDowngraded);

    return () => {
      paymentManager.off('paymentSuccess', handlePaymentSuccess);
      paymentManager.off('paymentError', handlePaymentError);
      paymentManager.off('tierUpgraded', handleTierUpgraded);
      paymentManager.off('tierDowngraded', handleTierDowngraded);
    };
  }, [userId, paymentManager]);

  // Load current tier
  const loadCurrentTier = useCallback(async (): Promise<void> => {
    try {
      const tier = await paymentManager.getCurrentTier();
      setState(prev => ({ ...prev, currentTier: tier }));
    } catch (error) {
      console.error('Failed to load current tier:', error);
    }
  }, [paymentManager]);

  // Load products
  const loadProducts = useCallback(async (): Promise<void> => {
    try {
      const productsList = await paymentManager.loadProducts();
      setState(prev => ({ ...prev, products: productsList }));
    } catch (error) {
      console.error('Failed to load products:', error);
      setState(prev => ({ 
        ...prev, 
        error: error instanceof Error ? error.message : 'Failed to load products' 
      }));
    }
  }, [paymentManager]);

  // Process payment - userId automatisch verfügbar
  const processPayment = useCallback(async (
    amount: number, 
    planType: string, 
    planId: string
  ): Promise<PaymentConfirmation> => {
    setState(prev => ({ ...prev, loading: true, error: null }));

    try {
      const result = await paymentManager.processPayment(amount, planType, planId);
      
      if (result.success) {
        // Refresh billing info and tier after successful payment
        await fetchUserBilling();
        await loadCurrentTier();
      }
      
      return result;
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Payment processing failed';
      setState(prev => ({ ...prev, error: errorMessage }));
      return { success: false, error: errorMessage };
    } finally {
      setState(prev => ({ ...prev, loading: false }));
    }
  }, [paymentManager, loadCurrentTier]);

  // Process test payment - vereinfacht
  const processTestPayment = useCallback(async (
    planType: string
  ): Promise<PaymentConfirmation> => {
    if (!paymentManager.isDemoModeEnabled()) {
      return { success: false, error: 'Test payments only available in demo mode' };
    }

    setState(prev => ({ ...prev, loading: true, error: null }));

    try {
      const product = state.products.find(p => p.id === planType);
      if (!product) {
        throw new Error(`Product ${planType} not found`);
      }

      const result = await paymentManager.processPayment(
        product.price, 
        planType, 
        planType
      );

      return result;
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Test payment failed';
      setState(prev => ({ ...prev, error: errorMessage }));
      return { success: false, error: errorMessage };
    } finally {
      setState(prev => ({ ...prev, loading: false }));
    }
  }, [paymentManager, state.products]);

  // Fetch user billing - userId automatisch verfügbar
  const fetchUserBilling = useCallback(async (): Promise<ApiResponse<BillingInfo>> => {
    try {
      const result = await paymentManager.getUserBilling();
      
      if (result.success && result.data) {
        setState(prev => ({ 
          ...prev, 
          currentBilling: result.data!,
          // Update tier from billing info if available
          currentTier: result.data!.paymentTier || prev.currentTier
        }));
      }
      
      return result;
    } catch (error) {
      console.error('Error fetching billing info:', error);
      const errorMessage = error instanceof Error ? error.message : 'Failed to fetch billing info';
      return { success: false, error: errorMessage };
    }
  }, [paymentManager]);

  // Fetch payment history - vereinfacht
  const fetchPaymentHistory = useCallback(async (
    page: number = 1, 
    limit: number = 10
  ): Promise<ApiResponse<PaymentHistoryEntry[]>> => {
    try {
      const result = await paymentManager.getPaymentHistory(page, limit);
      
      if (result.success && result.data) {
        setState(prev => ({ ...prev, paymentHistory: result.data! }));
      }
      
      return result;
    } catch (error) {
      console.error('Error fetching payment history:', error);
      const errorMessage = error instanceof Error ? error.message : 'Failed to fetch payment history';
      return { success: false, error: errorMessage, data: [] };
    }
  }, [paymentManager]);

  // Upgrade Tier - vereinfacht
  const upgradeTier = useCallback(async (
    targetTier: PaymentTier, 
    billingCycle: 'monthly' | 'yearly' = 'monthly'
  ): Promise<ApiResponse<PaymentConfirmation>> => {
    setState(prev => ({ ...prev, loading: true, error: null }));

    try {
      const result = await paymentManager.upgradeTier(targetTier, billingCycle);
      
      if (result.success) {
        setState(prev => ({ ...prev, currentTier: targetTier }));
        // Refresh billing after upgrade
        await fetchUserBilling();
      }

      return result;
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to upgrade tier';
      setState(prev => ({ ...prev, error: errorMessage }));
      return { success: false, error: errorMessage };
    } finally {
      setState(prev => ({ ...prev, loading: false }));
    }
  }, [paymentManager, fetchUserBilling]);

  // Downgrade Tier - vereinfacht
  const downgradeTier = useCallback(async (
    targetTier: PaymentTier
  ): Promise<ApiResponse<boolean>> => {
    setState(prev => ({ ...prev, loading: true, error: null }));

    try {
      const result = await paymentManager.downgradeTier(targetTier);
      
      if (result.success) {
        setState(prev => ({ ...prev, currentTier: targetTier }));
        // Refresh billing after downgrade
        await fetchUserBilling();
      }

      return result;
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to downgrade tier';
      setState(prev => ({ ...prev, error: errorMessage }));
      return { success: false, error: errorMessage };
    } finally {
      setState(prev => ({ ...prev, loading: false }));
    }
  }, [paymentManager, fetchUserBilling]);

  // Feature Access Check
  const canAccessFeature = useCallback((feature: keyof PaymentTierConfig['features']): boolean => {
    return paymentManager.canAccessFeature(state.currentTier, feature);
  }, [paymentManager, state.currentTier]);

  // Get Tier Config
  const getTierConfig = useCallback((tier: PaymentTier): PaymentTierConfig => {
    return paymentManager.getTierConfig(tier);
  }, [paymentManager]);

  // Get Upgrade Recommendation
  const getUpgradeRecommendation = useCallback((): TierUpgrade | null => {
    return paymentManager.getUpgradeRecommendation(state.currentTier);
  }, [paymentManager, state.currentTier]);

  // Helper functions
  const clearError = useCallback((): void => {
    setState(prev => ({ ...prev, error: null }));
  }, []);

  const getProductById = useCallback((productId: string): PaymentProduct | undefined => {
    return state.products.find(p => p.id === productId);
  }, [state.products]);

  const isSubscriptionActive = useCallback((): boolean => {
    return state.currentBilling?.subscription?.status === 'active';
  }, [state.currentBilling]);

  const getSubscriptionPlan = useCallback((): string => {
    return state.currentBilling?.subscription?.plan || 'free';
  }, [state.currentBilling]);

  return {
    // Core payment functions - vereinfacht
    processPayment,
    processTestPayment,
    fetchUserBilling,
    fetchPaymentHistory,

    // Tier Management
    currentTier: state.currentTier,
    availableTiers: state.availableTiers,
    upgradeTier,
    downgradeTier,
    canAccessFeature,
    getTierConfig,
    getUpgradeRecommendation,

    // State
    loading: state.loading,
    error: state.error,
    products: state.products,
    currentBilling: state.currentBilling,
    paymentHistory: state.paymentHistory,

    // Helper functions
    clearError,
    loadProducts,
    getProductById,
    isSubscriptionActive,
    getSubscriptionPlan,

    // Config
    isDemoMode: paymentManager.isDemoModeEnabled(),
    userId // NEU: User-ID verfügbar machen
  };
};

// ===================================================================
// SPECIALIZED HOOKS - Angepasst für user-spezifische Manager
// ===================================================================

/**
 * Hook for subscription management
 */
export const useSubscription = (userId: string) => {
  const { 
    isSubscriptionActive, 
    getSubscriptionPlan,
    currentTier,
    upgradeTier,
    loading,
    error 
  } = usePayment(userId);

  const [subscription, setSubscription] = useState<Subscription | null>(null);

  return {
    subscription,
    isActive: isSubscriptionActive(),
    currentPlan: getSubscriptionPlan(),
    currentTier,
    upgradeTier: (targetTier: PaymentTier, billingCycle?: 'monthly' | 'yearly') =>
      upgradeTier(targetTier, billingCycle),
    loading,
    error
  };
};

/**
 * Hook for Tier Management
 */
export const usePaymentTier = (userId: string) => {
  const {
    currentTier,
    availableTiers,
    upgradeTier,
    downgradeTier,
    canAccessFeature,
    getTierConfig,
    getUpgradeRecommendation,
    loading,
    error
  } = usePayment(userId);

  const currentTierConfig = getTierConfig(currentTier);
  const upgradeRecommendation = getUpgradeRecommendation();

  return {
    // Current Tier Info
    currentTier,
    currentTierConfig,
    
    // Available Options
    availableTiers,
    upgradeRecommendation,
    
    // Actions - vereinfacht (keine userId nötig)
    upgradeTo: (targetTier: PaymentTier, billingCycle?: 'monthly' | 'yearly') =>
      upgradeTier(targetTier, billingCycle),
    downgradeTo: (targetTier: PaymentTier) =>
      downgradeTier(targetTier),
    
    // Feature Checks
    canAccess: canAccessFeature,
    hasFeature: (feature: keyof PaymentTierConfig['features']): boolean =>
      canAccessFeature(feature),
    
    // Convenience Getters
    isFreeTier: currentTier === 'free',
    isBasicTier: currentTier === 'basic',
    isPremiumTier: currentTier === 'premium',
    isUltimateTier: currentTier === 'ultimate',
    
    // State
    loading,
    error
  };
};

export default usePayment;