// ===================================================================

import React, { useEffect, useState } from 'react';
import styled from 'styled-components';

const SuccessContainer = styled.div`
  max-width: 600px;
  margin: 0 auto;
  text-align: center;
  background: white;
  border-radius: 12px;
  padding: 3rem;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.1);
`;

const SuccessIcon = styled.div`
  font-size: 4rem;
  margin-bottom: 1rem;
  animation: bounce 2s infinite;
  
  @keyframes bounce {
    0%, 20%, 50%, 80%, 100% {
      transform: translateY(0);
    }
    40% {
      transform: translateY(-10px);
    }
    60% {
      transform: translateY(-5px);
    }
  }
`;

const SuccessTitle = styled.h1`
  color: #48bb78;
  margin-bottom: 1rem;
  font-size: 2.5rem;
`;

const SuccessMessage = styled.p`
  color: #4a5568;
  font-size: 1.2rem;
  margin-bottom: 2rem;
  line-height: 1.6;
`;

const ActionButton = styled.button`
  background: #4299e1;
  color: white;
  border: none;
  padding: 1rem 2rem;
  border-radius: 8px;
  font-size: 1.1rem;
  cursor: pointer;
  margin: 0 0.5rem;
  font-weight: 600;
  transition: background-color 0.2s;
  
  &:hover {
    background: #3182ce;
  }
  
  &.secondary {
    background: #718096;
    
    &:hover {
      background: #4a5568;
    }
  }
`;

const SuccessDetails = styled.div`
  background: #f0fff4;
  border: 1px solid #9ae6b4;
  border-radius: 8px;
  padding: 1.5rem;
  margin: 2rem 0;
  text-align: left;
`;

const DemoNotice = styled.div`
  background: #e6fffa;
  border: 1px solid #81e6d9;
  border-radius: 8px;
  padding: 1rem;
  margin-bottom: 2rem;
  
  h4 {
    margin: 0 0 0.5rem 0;
    color: #234e52;
    font-size: 1rem;
  }
  
  p {
    margin: 0;
    color: #285e61;
    font-size: 0.9rem;
  }
`;

const NextSteps = styled.div`
  background: #f7fafc;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 1.5rem;
  margin: 2rem 0;
  text-align: left;
  
  h4 {
    margin: 0 0 1rem 0;
    color: #2d3748;
  }
  
  ul {
    margin: 0;
    padding-left: 1.5rem;
    color: #4a5568;
    
    li {
      margin-bottom: 0.5rem;
    }
  }
`;

export const PaymentSuccess: React.FC = () => {
  const [isDemoMode, setIsDemoMode] = useState(false);
  const [countdown, setCountdown] = useState(10);

  useEffect(() => {
    // Check if we're in demo mode
    const demoMode = process.env.REACT_APP_DEMO_MODE === 'true';
    setIsDemoMode(demoMode);

    // Auto-redirect countdown
    const timer = setInterval(() => {
      setCountdown(prev => {
        if (prev <= 1) {
          clearInterval(timer);
          handleStartGaming();
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timer);
  }, []);

  const handleStartGaming = () => {
    window.location.href = '/games';
  };

  const handleViewBilling = () => {
    window.location.href = '/billing';
  };

  const handleBackToPricing = () => {
    window.location.href = '/pricing';
  };

  return (
    <SuccessContainer>
      {isDemoMode && (
        <DemoNotice>
          <h4>🎭 Demo Payment Successful!</h4>
          <p>
            This was a demonstration payment. No real money was charged, but you can 
            explore all the features as if you had a real subscription!
          </p>
        </DemoNotice>
      )}

      <SuccessIcon>🎉</SuccessIcon>
      
      <SuccessTitle>
        {isDemoMode ? 'Demo Payment Successful!' : 'Payment Successful!'}
      </SuccessTitle>
      
      <SuccessMessage>
        {isDemoMode 
          ? 'Thank you for trying our demo payment system! Your demo subscription is now active and you have access to all premium features in the demonstration environment.'
          : 'Thank you for your subscription! Your account has been upgraded and you now have access to all premium features. Start enjoying your enhanced gaming experience!'
        }
      </SuccessMessage>

      <SuccessDetails>
        <h4 style={{ margin: '0 0 1rem 0', color: '#276749' }}>
          ✅ What You Now Have Access To:
        </h4>
        <ul style={{ margin: 0, paddingLeft: '1.5rem', color: '#2d3748' }}>
          <li>All premium games and content</li>
          <li>Multiplayer gaming with friends</li>
          <li>Global leaderboards and rankings</li>
          <li>Game history and progress tracking</li>
          <li>Priority customer support</li>
          <li>Ad-free gaming experience</li>
          {isDemoMode && (
            <li style={{ color: '#4299e1', fontWeight: 'bold' }}>
              🎭 Full demo environment exploration
            </li>
          )}
        </ul>
      </SuccessDetails>

      <NextSteps>
        <h4>🚀 Next Steps:</h4>
        <ul>
          <li>Explore all available games in your new premium account</li>
          <li>Set up your gaming profile and preferences</li>
          <li>Invite friends to play multiplayer games</li>
          <li>Check out exclusive premium content</li>
          {isDemoMode && (
            <li>
              <strong>Demo Mode:</strong> Feel free to test all features - everything is safe to explore!
            </li>
          )}
        </ul>
      </NextSteps>
      
      <div>
        <ActionButton onClick={handleStartGaming}>
          Start Gaming {countdown > 0 && `(${countdown}s)`}
        </ActionButton>
        
        <ActionButton 
          onClick={handleViewBilling}
          className="secondary"
        >
          View Billing
        </ActionButton>
        
        {isDemoMode && (
          <ActionButton 
            onClick={handleBackToPricing}
            className="secondary"
          >
            Try Another Plan
          </ActionButton>
        )}
      </div>

      {countdown > 0 && (
        <p style={{ 
          marginTop: '2rem', 
          color: '#718096', 
          fontSize: '0.9rem' 
        }}>
          Automatically redirecting to games in {countdown} seconds...
        </p>
      )}

      {isDemoMode && (
        <div style={{ 
          marginTop: '2rem', 
          padding: '1rem', 
          background: '#f0fff4',
          borderRadius: '8px',
          fontSize: '0.9rem',
          color: '#276749'
        }}>
          <strong>💡 Demo Tip:</strong> This success page shows what real users would see 
          after completing a payment. All premium features are now unlocked in the demo environment!
        </div>
      )}
    </SuccessContainer>
  );
};

export default PaymentSuccess;