/**
 * PongMultiplayer.tsx - Simplified Version
 */

import React, { useState, useEffect, useRef } from 'react';
import styled from 'styled-components';

// ==================== TYPES ====================
interface PongGameState {
  ball: {
    x: number;
    y: number;
    radius: number;
  };
  paddles: {
    left: { y: number; height: number };
    right: { y: number; height: number };
  };
  scores: {
    left: number;
    right: number;
  };
  status?: string;
}

interface PongMultiplayerProps {
  socket: any;
  sessionId: string;
  currentUser: any;
  onLeave: () => void;
}

// ==================== STYLED COMPONENTS ====================
const PongContainer = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  background: #0a0a0a;
`;

const GameHeader = styled.div`
  display: flex;
  justify-content: space-between;
  width: 800px;
  margin-bottom: 20px;
  padding: 15px;
  background: rgba(255, 255, 255, 0.05);
  border-radius: 8px;
`;

const PlayerInfo = styled.div<{ $side: 'left' | 'right' }>`
  text-align: ${props => props.$side};
  color: #fff;
`;

const PlayerName = styled.div`
  font-size: 1.2rem;
  font-weight: bold;
  margin-bottom: 5px;
`;

const Score = styled.div`
  font-size: 2.5rem;
  font-weight: bold;
  color: #00ff88;
`;

const CanvasContainer = styled.div`
  position: relative;
  border: 3px solid #00ff88;
  border-radius: 8px;
  box-shadow: 0 0 20px rgba(0, 255, 136, 0.3);
`;

const GameCanvas = styled.canvas`
  display: block;
  background: #000;
`;

const GameOverlay = styled.div`
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.8);
  color: #fff;
  font-size: 2rem;
  font-weight: bold;
`;

const ControlsHint = styled.div`
  margin-top: 20px;
  color: #888;
  font-size: 0.9rem;
`;

const LeaveButton = styled.button`
  position: absolute;
  top: 20px;
  right: 20px;
  background: #ff4444;
  border: none;
  padding: 10px 20px;
  border-radius: 6px;
  color: white;
  cursor: pointer;
  font-weight: bold;

  &:hover {
    background: #ff6666;
  }
`;   

const DisconnectOverlay = styled.div`
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.9);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
`;

const DisconnectMessage = styled.div`
  background: rgba(255, 50, 50, 0.9);
  color: white;
  padding: 30px 50px;
  border-radius: 10px;
  font-size: 24px;
  font-weight: bold;
  text-align: center;
  box-shadow: 0 0 30px rgba(255, 50, 50, 0.5);
`;

// ==================== COMPONENT ====================
const PongMultiplayer: React.FC<PongMultiplayerProps> = ({ 
  socket, 
  sessionId, 
  currentUser,
  onLeave 
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const CANVAS_WIDTH = 800;
  const CANVAS_HEIGHT = 600;

  const [gameState, setGameState] = useState<PongGameState>({
    ball: { x: 400, y: 300, radius: 8 },
    paddles: {
      left: { y: 250, height: 100 },
      right: { y: 250, height: 100 }
    },
    scores: { left: 0, right: 0 },
    status: 'waiting'
  });

  const [disconnectMessage, setDisconnectMessage] = useState<string | null>(null);
  const [players, setPlayers] = useState<any>({});
  const [mySide, setMySide] = useState<'left' | 'right' | null>(null);
  const [countdown, setCountdown] = useState<number | null>(null);
  const [showOverlay, setShowOverlay] = useState(true);

  // ==================== SOCKET HANDLERS ====================
  useEffect(() => {
    if (!socket || !sessionId) return;
  
    const handlePlayerDisconnected = (data: { playerId: string; username: string }) => {
      console.log('⚠️ Player disconnected:', data.username);
      setDisconnectMessage(`${data.username} has disconnected. Returning to lobby...`);
      
      setTimeout(() => {
        onLeave();
      }, 3000);
    };
  
    socket.on('player-disconnected', handlePlayerDisconnected);
  
    return () => {
      socket.off('player-disconnected', handlePlayerDisconnected);
    };
  }, [socket, sessionId, onLeave]);

  useEffect(() => {
    if (!socket) return;

    const handleSessionJoined = () => {
      console.log('🔵 SESSION-JOINED received, emitting pong:join with sessionId:', sessionId);
      socket.emit('pong:join', sessionId);
    };

    const handleRoomJoined = (data: any) => {
      console.log('🔵 ROOM-JOINED received:', data);
      setMySide(data.side);
      setPlayers(data.players);
    };

    const handleGameState = (state: PongGameState) => {
      setGameState(state);
      if (state.status === 'playing') {
        setShowOverlay(false);
      }
    };

    const handleCountdown = (count: number) => {
      setCountdown(count);
      if (count === 0) {
        setTimeout(() => setCountdown(null), 500);
      }
    };

    const handleGameOver = (data: any) => {
      setShowOverlay(true);
      setGameState(prev => ({ ...prev, status: 'finished' }));
    };

    socket.on('session-joined', handleSessionJoined);
    socket.on('pong:room-joined', handleRoomJoined);
    socket.on('pong:game-state', handleGameState);
    socket.on('pong:countdown', handleCountdown);
    socket.on('pong:game-over', handleGameOver);

    return () => {
      socket.off('session-joined', handleSessionJoined);
      socket.off('pong:room-joined', handleRoomJoined);
      socket.off('pong:game-state', handleGameState);
      socket.off('pong:countdown', handleCountdown);
      socket.off('pong:game-over', handleGameOver);
    };
  }, [socket, sessionId]);
  
  useEffect(() => {
    if (!socket || !sessionId) return;
  
    const handlePlayerDisconnected = (data: { playerId: string; username: string }) => {
      console.log('⚠️ Player disconnected:', data.username);
      
      // Zeige eine Benachrichtigung (du kannst auch ein Modal verwenden)
      alert(`${data.username} has disconnected. Returning to lobby...`);
      
      // Gehe zurück zur Lobby
      window.location.href = '/lobby';
    };
  
    socket.on('player-disconnected', handlePlayerDisconnected);
  
    return () => {
      socket.off('player-disconnected', handlePlayerDisconnected);
    };
  }, [socket, sessionId]);
    
  // ==================== KEYBOARD INPUT ====================
  useEffect(() => {
    if (!socket || !mySide) return;
  
    const handleKeyDown = (e: KeyboardEvent) => {
      // Nur Spiel-Tasten verarbeiten
      const gameKeys = ['w', 'W', 's', 'S', 'ArrowUp', 'ArrowDown'];
      if (!gameKeys.includes(e.key)) return;
      
      // Verhindere Browser-Scroll
      e.preventDefault();
      
      // Ignoriere während Overlay
      if (showOverlay) return;
      
      let newY = gameState.paddles[mySide].y;
      const speed = 15;
  
      if (mySide === 'left') {
        if (e.key === 'w' || e.key === 'W') newY -= speed;
        if (e.key === 's' || e.key === 'S') newY += speed;
      } else {
        if (e.key === 'ArrowUp') newY -= speed;
        if (e.key === 'ArrowDown') newY += speed;
      }
  
      newY = Math.max(0, Math.min(newY, CANVAS_HEIGHT - gameState.paddles[mySide].height));
  
      if (newY !== gameState.paddles[mySide].y) {
        socket.emit('pong:paddle-move', { y: newY });
      }
    };
  
    // An document statt window
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [socket, mySide, showOverlay, gameState.paddles, CANVAS_HEIGHT]);

  // ==================== RENDERING ====================
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Center line
    ctx.strokeStyle = '#333';
    ctx.setLineDash([10, 10]);
    ctx.beginPath();
    ctx.moveTo(CANVAS_WIDTH / 2, 0);
    ctx.lineTo(CANVAS_WIDTH / 2, CANVAS_HEIGHT);
    ctx.stroke();
    ctx.setLineDash([]);

    // Paddles
    ctx.fillStyle = '#00ff88';
    ctx.fillRect(20, gameState.paddles.left.y, 10, gameState.paddles.left.height);
    ctx.fillRect(CANVAS_WIDTH - 30, gameState.paddles.right.y, 10, gameState.paddles.right.height);

    // Ball
    ctx.beginPath();
    ctx.arc(gameState.ball.x, gameState.ball.y, gameState.ball.radius, 0, Math.PI * 2);
    ctx.fillStyle = '#fff';
    ctx.fill();
  }, [gameState]);

  // ==================== RENDER ====================
  return (
    <PongContainer>
      <LeaveButton onClick={onLeave}>Leave Game</LeaveButton>
      <GameHeader>
        <PlayerInfo $side="left">
          <PlayerName>{players.left?.displayName || 'Waiting...'}</PlayerName>
          <Score>{gameState.scores.left}</Score>
        </PlayerInfo>
        <PlayerInfo $side="right">
          <PlayerName>{players.right?.displayName || 'Waiting...'}</PlayerName>
          <Score>{gameState.scores.right}</Score>
        </PlayerInfo>
      </GameHeader>
      <CanvasContainer>
        <GameCanvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} />
        {(showOverlay || countdown !== null) && (
          <GameOverlay>
            {countdown !== null ? (countdown === 0 ? 'GO!' : countdown) : 'Waiting for opponent...'}
          </GameOverlay>
        )}
        {disconnectMessage && (
          <DisconnectOverlay>
            <DisconnectMessage>{disconnectMessage}</DisconnectMessage>
          </DisconnectOverlay>
        )}
      </CanvasContainer>
      <ControlsHint>
        {mySide === 'left' && 'Controls: W (up) / S (down)'}
        {mySide === 'right' && 'Controls: Arrow Up / Arrow Down'}
      </ControlsHint>
    </PongContainer>
  );
};

export default PongMultiplayer;