import React, { useState, useEffect } from 'react';
import { useAuth } from '../../managers/AuthManager/hooks/useAuth';
import { usePayment } from '../../managers/PaymentManager/hooks/usePayment';
import type { BillingInfo, PaymentHistoryEntry } from '../../managers/PaymentManager/PaymentManager';
import './BillingDashboard.css'; // Styling

export const BillingDashboard: React.FC = () => {
  const { user } = useAuth();
  
  // usePayment mit userId Parameter
  const { 
    fetchUserBilling, 
    fetchPaymentHistory, 
    isDemoMode,
    currentBilling,
    paymentHistory,
    currentTier,
    availableTiers,
    upgradeTier,
    downgradeTier,
    canAccessFeature,
    loading,
    error,
    clearError
  } = usePayment(user?.id?.toString() || '');

  const [billing, setBilling] = useState<BillingInfo | null>(null);
  const [payments, setPayments] = useState<PaymentHistoryEntry[]>([]);
  const [activeTab, setActiveTab] = useState<'overview' | 'billing' | 'history' | 'settings'>('overview');
  const [showUpgradeModal, setShowUpgradeModal] = useState(false);

  useEffect(() => {
    if (!user?.id) return;

    const loadData = async () => {
      try {
        // Billing Info laden
        const billingResponse = await fetchUserBilling();
        if (billingResponse.success && billingResponse.data) {
          setBilling(billingResponse.data);
        }

        // Payment History laden
        const paymentsResponse = await fetchPaymentHistory(1, 20);
        if (paymentsResponse.success && paymentsResponse.data) {
          setPayments(paymentsResponse.data);
        }
      } catch (err) {
        console.error('Error loading billing data:', err);
      }
    };

    loadData();
  }, [user?.id, fetchUserBilling, fetchPaymentHistory]);

  const effectiveBilling = billing || currentBilling;
  const effectivePayments = payments.length > 0 ? payments : paymentHistory;

  const handleUpgrade = async (targetTier: string) => {
    try {
      const result = await upgradeTier(targetTier as any, 'monthly');
      if (result.success) {
        setShowUpgradeModal(false);
        // Reload data
        const billingResponse = await fetchUserBilling();
        if (billingResponse.success && billingResponse.data) {
          setBilling(billingResponse.data);
        }
      }
    } catch (err) {
      console.error('Upgrade failed:', err);
    }
  };

  if (!user) {
    return (
      <div className="billing-dashboard">
        <div className="auth-required">
          <h2>Authentication Required</h2>
          <p>Please log in to view your billing information.</p>
        </div>
      </div>
    );
  }

  if (loading && !billing && !effectiveBilling) {
    return (
      <div className="billing-dashboard">
        <div className="loading-spinner">
          <div className="spinner"></div>
          <p>Loading billing information...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="billing-dashboard">
      {/* Header */}
      <div className="dashboard-header">
        <h1>Billing Dashboard</h1>
        {isDemoMode && (
          <div className="demo-badge">
            🧪 Demo Mode
          </div>
        )}
        <div className="user-info">
          <span>Welcome, {user.username || user.email}</span>
        </div>
      </div>

      {/* Error Message */}
      {error && (
        <div className="error-banner">
          <span>❌ {error}</span>
          <button onClick={clearError} className="close-btn">×</button>
        </div>
      )}

      {/* Tab Navigation */}
      <div className="tab-navigation">
        {['overview', 'billing', 'history', 'settings'].map((tab) => (
          <button
            key={tab}
            className={`tab-btn ${activeTab === tab ? 'active' : ''}`}
            onClick={() => setActiveTab(tab as any)}
          >
            {tab.charAt(0).toUpperCase() + tab.slice(1)}
          </button>
        ))}
      </div>

      {/* Tab Content */}
      <div className="tab-content">
        {/* Overview Tab */}
        {activeTab === 'overview' && (
          <div className="overview-tab">
            <div className="stats-grid">
              <div className="stat-card">
                <h3>Current Plan</h3>
                <div className="stat-value">
                  {effectiveBilling?.subscription?.plan || currentTier || 'Free'}
                </div>
                <div className="stat-status">
                  {effectiveBilling?.subscription?.status || 'Active'}
                </div>
              </div>
              
              <div className="stat-card">
                <h3>Next Billing</h3>
                <div className="stat-value">
                  {effectiveBilling?.subscription?.currentPeriodEnd
                    ? new Date(effectiveBilling.subscription.currentPeriodEnd).toLocaleDateString()
                    : 'N/A'
                  }
                </div>
              </div>
              
              <div className="stat-card">
                <h3>Total Payments</h3>
                <div className="stat-value">{effectivePayments.length}</div>
              </div>
              
              <div className="stat-card">
                <h3>Account Status</h3>
                <div className="stat-value good">
                  {effectiveBilling?.subscription?.status === 'active' ? 'Active' : 'Inactive'}
                </div>
              </div>
            </div>

            {/* Quick Actions */}
            <div className="quick-actions">
              <h3>Quick Actions</h3>
              <div className="action-buttons">
                <button 
                  className="action-btn primary"
                  onClick={() => setShowUpgradeModal(true)}
                >
                  Upgrade Plan
                </button>
                <button 
                  className="action-btn secondary"
                  onClick={() => setActiveTab('billing')}
                >
                  View Billing
                </button>
                <button 
                  className="action-btn secondary"
                  onClick={() => setActiveTab('history')}
                >
                  Payment History
                </button>
              </div>
            </div>

            {/* Feature Access */}
            <div className="feature-access">
              <h3>Your Plan Features</h3>
              <div className="features-grid">
                {[
                  { key: 'api_calls', name: 'API Calls', icon: '🔌' },
                  { key: 'storage', name: 'Storage', icon: '💾' },
                  { key: 'support', name: 'Priority Support', icon: '🎧' },
                  { key: 'analytics', name: 'Advanced Analytics', icon: '📊' }
                ].map((feature) => (
                  <div key={feature.key} className="feature-item">
                    <span className="feature-icon">{feature.icon}</span>
                    <span className="feature-name">{feature.name}</span>
                    <span className={`feature-status ${canAccessFeature(feature.key as any) ? 'enabled' : 'disabled'}`}>
                      {canAccessFeature(feature.key as any) ? '✓' : '✗'}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Billing Tab */}
        {activeTab === 'billing' && (
          <div className="billing-tab">
            <div className="billing-section">
              <h3>Current Subscription</h3>
              {effectiveBilling?.subscription ? (
                <div className="subscription-card">
                  <div className="subscription-header">
                    <h4>{effectiveBilling.subscription.plan}</h4>
                    <span className={`status-badge ${effectiveBilling.subscription.status}`}>
                      {effectiveBilling.subscription.status}
                    </span>
                  </div>
                  <div className="subscription-details">
                    <div className="detail-row">
                      <span>Plan:</span>
                      <span>{effectiveBilling.subscription.plan}</span>
                    </div>
                    <div className="detail-row">
                      <span>Status:</span>
                      <span>{effectiveBilling.subscription.status}</span>
                    </div>
                    {effectiveBilling.subscription.currentPeriodEnd && (
                      <div className="detail-row">
                        <span>Next Billing:</span>
                        <span>{new Date(effectiveBilling.subscription.currentPeriodEnd).toLocaleDateString()}</span>
                      </div>
                    )}
                    {effectiveBilling.stripeCustomerId && (
                      <div className="detail-row">
                        <span>Customer ID:</span>
                        <span>{effectiveBilling.stripeCustomerId}</span>
                      </div>
                    )}
                  </div>
                </div>
              ) : (
                <div className="no-subscription">
                  <p>No active subscription</p>
                  <button 
                    className="upgrade-btn"
                    onClick={() => setShowUpgradeModal(true)}
                  >
                    Choose a Plan
                  </button>
                </div>
              )}
            </div>

            {/* Plan Options */}
            <div className="plan-options">
              <h3>Available Plans</h3>
              <div className="plans-grid">
                {availableTiers.map((tier) => (
                  <div key={tier.name} className={`plan-card ${currentTier === tier.name ? 'current' : ''}`}>
                    <h4>{tier.name}</h4>
                    <div className="price">
                      ${tier.monthlyPrice}/month
                    </div>
                    <ul className="features-list">
                      {Object.entries(tier.features).map(([key, value]) => (
                        <li key={key}>
                          {key.replace('_', ' ')}: {value === true ? '✓' : value}
                        </li>
                      ))}
                    </ul>
                    {currentTier !== tier.name && (
                      <button 
                        className="select-plan-btn"
                        onClick={() => handleUpgrade(tier.name)}
                        disabled={loading}
                      >
                        {loading ? 'Processing...' : 'Select Plan'}
                      </button>
                    )}
                    {currentTier === tier.name && (
                      <div className="current-plan">Current Plan</div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Payment History Tab */}
        {activeTab === 'history' && (
          <div className="history-tab">
            <h3>Payment History</h3>
            {effectivePayments.length > 0 ? (
              <div className="payment-table">
                <div className="table-header">
                  <div className="col">Date</div>
                  <div className="col">Amount</div>
                  <div className="col">Plan</div>
                  <div className="col">Status</div>
                  <div className="col">Actions</div>
                </div>
                {effectivePayments.map((payment) => (
                  <div key={payment.id} className="table-row">
                    <div className="col">
                      {new Date(payment.paidAt || payment.created_at).toLocaleDateString()}
                    </div>
                    <div className="col">
                      ${payment.amount} {payment.currency?.toUpperCase()}
                    </div>
                    <div className="col">{payment.planType}</div>
                    <div className="col">
                      <span className={`status-badge ${payment.status}`}>
                        {payment.status}
                      </span>
                    </div>
                    <div className="col">
                      <button className="action-link">View Details</button>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="no-payments">
                <p>No payment history available</p>
                <p>Make your first payment to see it here!</p>
              </div>
            )}
          </div>
        )}

        {/* Settings Tab */}
        {activeTab === 'settings' && (
          <div className="settings-tab">
            <h3>Billing Settings</h3>
            <div className="settings-section">
              <h4>Payment Methods</h4>
              <p>Manage your payment methods and billing preferences.</p>
              <button className="settings-btn">Add Payment Method</button>
            </div>
            
            <div className="settings-section">
              <h4>Billing Address</h4>
              <p>Update your billing address for invoices.</p>
              <button className="settings-btn">Update Address</button>
            </div>
            
            <div className="settings-section">
              <h4>Notifications</h4>
              <p>Configure billing and payment notifications.</p>
              <button className="settings-btn">Notification Settings</button>
            </div>
            
            <div className="settings-section danger">
              <h4>Cancel Subscription</h4>
              <p>Permanently cancel your subscription. This action cannot be undone.</p>
              <button className="settings-btn danger">Cancel Subscription</button>
            </div>
          </div>
        )}
      </div>

      {/* Upgrade Modal */}
      {showUpgradeModal && (
        <div className="modal-overlay" onClick={() => setShowUpgradeModal(false)}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>Upgrade Your Plan</h3>
              <button onClick={() => setShowUpgradeModal(false)}>×</button>
            </div>
            <div className="modal-content">
              <p>Choose a plan that fits your needs:</p>
              <div className="modal-plans">
                {availableTiers.filter(tier => tier.name !== currentTier).map((tier) => (
                  <div key={tier.name} className="modal-plan">
                    <h4>{tier.name}</h4>
                    <div className="price">${tier.monthlyPrice}/month</div>
                    <button 
                      onClick={() => handleUpgrade(tier.name)}
                      disabled={loading}
                      className="upgrade-btn"
                    >
                      {loading ? 'Processing...' : `Upgrade to ${tier.name}`}
                    </button>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};