import React, { useState, useRef, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import styled from 'styled-components';
import { useGameIntegration } from '../../../managers/AuthManager/hooks/useAuth';
import { GameLayout, useGameHUD } from '../../../shared/layouts/GameLayout';
import { RetroButton } from '../../../shared/ui/RetroButton';

// ===================================
// INTERFACES & TYPES
// ===================================

interface Card {
  id: number;
  symbol: string;
  imagePath?: string;  
  imageLoaded?: HTMLImageElement;  
  x: number;
  y: number;
  width: number;
  height: number;
  flipped: boolean;
  matched: boolean;
  color: string;
}

interface GameStats {
  moves: number;
  matches: number;
  timeElapsed: number;
  score: number;
}

interface MemoryGameState {
  gameStatus: 'idle' | 'playing' | 'paused' | 'completed';
  cards: Card[];
  flippedCards: Card[];
  stats: GameStats;
  gameStartTime: number;
  difficulty: 'easy' | 'medium' | 'hard' | 'expert';
}

interface GameSettings {
  difficulty: 'easy' | 'medium' | 'hard' | 'expert';
  canvasSize: 'small' | 'medium' | 'large';
  cardStyle: 'symbols' | 'colors' | 'mixed' | 'paintings';
  animationSpeed: 'slow' | 'normal' | 'fast';
  hudPosition: 'top' | 'bottom' | 'both';
}

// ===================================
// CONSTANTS & SETTINGS
// ===================================

const DIFFICULTIES = {
  easy: { pairs: 6, cols: 3, rows: 4 },
  medium: { pairs: 8, cols: 4, rows: 4 },
  hard: { pairs: 12, cols: 4, rows: 6 },
  expert: { pairs: 18, cols: 6, rows: 6 }
};

const CANVAS_SIZES = {
  small: { width: 400, height: 500 },
  medium: { width: 500, height: 600 },
  large: { width: 600, height: 700 }
};

const SYMBOLS = ['🎮', '🕹️', '🎯', '🎲', '🃏', '🎪', '🎨', '🎭', '🎪', '🎺', '🎸', '🎤', '🎧', '🎷', '🥁', '🎻', '🎹', '🎬', '🎨', '⭐'];
const COLOR_SYMBOLS = ['🔴', '🟠', '🟡', '🟢', '🔵', '🟣', '🟤', '⚫', '⚪', '🔺', '🔸', '🔹', '💎', '🌟', '✨', '💫', '⭐', '🌙', '☀️', '🌈'];
const CARD_COLORS = ['#ff6b9d', '#4ecdc4', '#45b7d1', '#96ceb4', '#feca57', '#ff9ff3', '#a55eea', '#26de81', '#fd79a8', '#fdcb6e'];

// NEU - Hier einfügen:
const PAINTING_PATHS = [
  '/images/memory/paintings/painting-01.jpg',
  '/images/memory/paintings/painting-02.jpg',
  '/images/memory/paintings/painting-03.jpg',
  '/images/memory/paintings/painting-04.jpg',
  '/images/memory/paintings/painting-05.jpg',
  '/images/memory/paintings/painting-06.jpg',
  '/images/memory/paintings/painting-07.jpg',
  '/images/memory/paintings/painting-08.jpg',
  '/images/memory/paintings/painting-09.jpg',
  '/images/memory/paintings/painting-10.jpg',
  '/images/memory/paintings/painting-11.jpg',
  '/images/memory/paintings/painting-12.jpg',
  '/images/memory/paintings/painting-13.jpg',
  '/images/memory/paintings/painting-14.jpg',
  '/images/memory/paintings/painting-15.jpg',
  '/images/memory/paintings/painting-16.jpg',
  '/images/memory/paintings/painting-17.jpg',
  '/images/memory/paintings/painting-18.jpg'
];

const ANIMATION_SPEEDS = {
  slow: 1500,
  normal: 1000,
  fast: 600
};

const DEFAULT_SETTINGS: GameSettings = {
  difficulty: 'medium',
  canvasSize: 'large',
  cardStyle: 'symbols',
  animationSpeed: 'normal',
  hudPosition: 'both'
};

// Dynamic Constants
let CURRENT_CANVAS_WIDTH = CANVAS_SIZES[DEFAULT_SETTINGS.canvasSize].width;
let CURRENT_CANVAS_HEIGHT = CANVAS_SIZES[DEFAULT_SETTINGS.canvasSize].height;
let FLIP_DURATION = ANIMATION_SPEEDS[DEFAULT_SETTINGS.animationSpeed];

// ===================================
// STYLED COMPONENTS
