/**
 * useAchievementManager Hook
 * Path: FRONTEND\src\managers\AchievementManager\hooks\useAchievementManager.ts
 * 
 * React Hook for AchievementManager integration with ScoreView component
 * Consumes Backend-First data structures through AchievementManager API client
 */

import { useState, useEffect, useCallback } from 'react';
import achievementManager from '../AchievementManager';  
import type { 
  Achievement, 
  LeaderboardEntry, 
  UserStatistics, 
  UserProgress,
  ScoreViewData,
  ScoreViewAchievement,
  ScoreViewLeaderboardEntry,
  ScoreViewUserStats
} from '../types';

interface UseAchievementManagerResult {
  achievements: ScoreViewAchievement[];
  leaderboard: ScoreViewLeaderboardEntry[];
  userStats: ScoreViewUserStats;
  userProgress: UserProgress | null;
  loading: boolean;
  error: string | null;
  lastUpdated: string | null;
  computedStats: {
    completionPercentage: number;
    unlockedCount: number;
    totalAchievements: number;
    userRank: number | null;
  };
  loadScoreViewData: () => Promise<void>;
  loadUserAchievements: () => Promise<ScoreViewAchievement[]>;
  loadLeaderboard: (gameId?: string | null, limit?: number) => Promise<ScoreViewLeaderboardEntry[]>;
  loadUserStatistics: () => Promise<ScoreViewUserStats>;
  loadUserProgress: () => Promise<UserProgress>;
  unlockAchievement: (achievementId: string, gameContext?: any) => Promise<any>;
  refreshData: () => Promise<void>;
  clearCacheAndReload: () => Promise<void>;
  isHealthy: () => Promise<boolean>;
  clearError: () => void;
  manager: typeof achievementManager;
}

interface UseScoreViewResult {
  achievements: ScoreViewAchievement[];
  leaderboard: ScoreViewLeaderboardEntry[];
  userStats: ScoreViewUserStats;
  loading: boolean;
  error: string | null;
  achievementsUnlockedCount: number;
  achievementsTotalCount: number;
  completionPercentage: number;
  refresh: () => Promise<void>;
  unlockAchievement: (achievementId: string, gameContext?: any) => Promise<any>;
  isReady: boolean;
}

export const useAchievementManager = (userId: string | null = null): UseAchievementManagerResult => {
  // State management
  const [achievements, setAchievements] = useState<ScoreViewAchievement[]>([]);
  const [leaderboard, setLeaderboard] = useState<ScoreViewLeaderboardEntry[]>([]);
  const [userStats, setUserStats] = useState<ScoreViewUserStats>({
    gamesPlayed: 0,
    totalScore: 0,
    achievementsUnlocked: 0,
    hoursPlayed: 0
  });
  const [userProgress, setUserProgress] = useState<UserProgress | null>(null);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [lastUpdated, setLastUpdated] = useState<string | null>(null);

  // Initialize AchievementManager
  useEffect(() => {
    achievementManager.initialize();
  }, []);

  /**
   * Load ScoreView data (all data for ScoreView component)
   * Replaces mock data in ScoreView.tsx with real API data
   */
  const loadScoreViewData = useCallback(async (): Promise<void> => {
    if (!userId) return;

    setLoading(true);
    setError(null);

    try {
      // Get formatted data for ScoreView component
      const scoreViewData = await achievementManager.getScoreViewData(userId);

      // Update state with backend data (replaces ScoreView mock data)
      setAchievements(scoreViewData.achievements);
      setLeaderboard(scoreViewData.leaderboard);
      setUserStats(scoreViewData.userStats);
      setLastUpdated(scoreViewData.metadata.lastUpdated);

      // Handle errors in metadata
      if (scoreViewData.metadata.error) {
        setError(`Data warning: ${scoreViewData.metadata.error}`);
      }

    } catch (err) {
      console.error('useAchievementManager: Load ScoreView data failed:', err);
      const errorMessage = err instanceof Error ? err.message : 'Unknown error';
      setError(errorMessage);
      
      // Keep existing data on error, don't reset to empty state
    } finally {
      setLoading(false);
    }
  }, [userId]);

  /**
   * Load user achievements only
   */
  const loadUserAchievements = useCallback(async (): Promise<ScoreViewAchievement[]> => {
    if (!userId) return [];

    try {
      const achievementsData = await achievementManager.getUserAchievements(userId);
      
      // Transform for ScoreView component format
      const formattedAchievements = achievementsData.achievements.map((achievement: Achievement) => ({
        id: achievement.id,
        title: achievement.title,
        description: achievement.description,
        icon: achievement.icon,
        unlocked: achievement.unlocked,
        unlockedAt: achievement.unlocked_at
      }));

      setAchievements(formattedAchievements);
      return formattedAchievements;

    } catch (err) {
      console.error('useAchievementManager: Load achievements failed:', err);
      throw err;
    }
  }, [userId]);

  /**
   * Load leaderboard only
   */
  const loadLeaderboard = useCallback(async (gameId: string | null = null, limit: number = 50): Promise<ScoreViewLeaderboardEntry[]> => {
    try {
      const leaderboardData = await achievementManager.getLeaderboard(gameId, limit);
      
      // Transform for ScoreView component format
      const formattedLeaderboard = leaderboardData.entries.map((entry: LeaderboardEntry) => ({
        rank: entry.rank,
        player: entry.username,
        score: entry.score,
        game: entry.game_name,
        isCurrentUser: entry.user_id === userId
      }));

      setLeaderboard(formattedLeaderboard);
      return formattedLeaderboard;

    } catch (err) {
      console.error('useAchievementManager: Load leaderboard failed:', err);
      throw err;
    }
  }, [userId]);

  /**
   * Load user statistics only
   */
  const loadUserStatistics = useCallback(async (): Promise<ScoreViewUserStats> => {
    if (!userId) {
      const defaultStats = {
        gamesPlayed: 0,
        totalScore: 0,
        achievementsUnlocked: 0,
        hoursPlayed: 0
      };
      setUserStats(defaultStats);
      return defaultStats;
    }

    try {
      const statisticsData = await achievementManager.getUserStatistics(userId);
      
      // Transform for ScoreView component format (matches UserStats interface)
      const formattedStats: ScoreViewUserStats = {
        gamesPlayed: statisticsData.games_played,
        totalScore: statisticsData.total_score,
        achievementsUnlocked: statisticsData.achievements_unlocked,
        hoursPlayed: statisticsData.hours_played
      };

      setUserStats(formattedStats);
      return formattedStats;

    } catch (err) {
      console.error('useAchievementManager: Load user statistics failed:', err);
      throw err;
    }
  }, [userId]);

  /**
   * Load user progress details
   */
  const loadUserProgress = useCallback(async (): Promise<UserProgress> => {
    if (!userId) throw new Error('User ID required');

    try {
      const progressData = await achievementManager.getUserProgress(userId);
      setUserProgress(progressData);
      return progressData;

    } catch (err) {
      console.error('useAchievementManager: Load user progress failed:', err);
      throw err;
    }
  }, [userId]);

  /**
   * Unlock achievement
   */
  const unlockAchievement = useCallback(async (achievementId: string, gameContext: any = {}): Promise<any> => {
    if (!userId) {
      throw new Error('User ID is required to unlock achievement');
    }

    try {
      const result = await achievementManager.unlockAchievement(userId, achievementId, gameContext);
      
      // Refresh data after successful unlock
      if (result.success) {
        await loadScoreViewData();
      }

      return result;

    } catch (err) {
      console.error('useAchievementManager: Unlock achievement failed:', err);
      throw err;
    }
  }, [userId, loadScoreViewData]);

  /**
   * Refresh all data
   */
  const refreshData = useCallback(async (): Promise<void> => {
    await loadScoreViewData();
  }, [loadScoreViewData]);

  /**
   * Clear cache and reload
   */
  const clearCacheAndReload = useCallback(async (): Promise<void> => {
    achievementManager.clearCache();
    await loadScoreViewData();
  }, [loadScoreViewData]);

  // Auto-load data when userId changes
  useEffect(() => {
    if (userId) {
      loadScoreViewData();
    }
  }, [userId, loadScoreViewData]);

  // Computed properties for ScoreView component
  const computedStats = {
    completionPercentage: achievements.length > 0 
      ? Math.round((achievements.filter(a => a.unlocked).length / achievements.length) * 100)
      : 0,
    unlockedCount: achievements.filter(a => a.unlocked).length,
    totalAchievements: achievements.length,
    userRank: leaderboard.find(entry => entry.isCurrentUser)?.rank || null
  };

  // Return hook interface
  return {
    // Data state (matches ScoreView component requirements)
    achievements,
    leaderboard,
    userStats,
    userProgress,
    
    // Loading and error state
    loading,
    error,
    lastUpdated,
    
    // Computed statistics
    computedStats,
    
    // Action methods
    loadScoreViewData,
    loadUserAchievements,
    loadLeaderboard,
    loadUserStatistics,
    loadUserProgress,
    unlockAchievement,
    refreshData,
    clearCacheAndReload,
    
    // Utility methods
    isHealthy: () => achievementManager.healthCheck(),
    clearError: () => setError(null),
    
    // Manager instance (for advanced usage)
    manager: achievementManager
  };
};

/**
 * Hook for ScoreView component specifically
 * Simplified interface that matches ScoreView.tsx current structure
 */
export const useScoreView = (userId: string | null = null): UseScoreViewResult => {
  const {
    achievements,
    leaderboard,
    userStats,
    loading,
    error,
    computedStats,
    loadScoreViewData,
    unlockAchievement,
    refreshData
  } = useAchievementManager(userId);

  // Auto-refresh every 5 minutes
  useEffect(() => {
    if (userId) {
      const interval = setInterval(() => {
        loadScoreViewData();
      }, 5 * 60 * 1000);

      return () => clearInterval(interval);
    }
  }, [userId, loadScoreViewData]);

  return {
    // Data formatted exactly for ScoreView.tsx
    achievements,
    leaderboard,
    userStats,
    
    // State
    loading,
    error,
    
    // Computed values
    achievementsUnlockedCount: computedStats.unlockedCount,
    achievementsTotalCount: computedStats.totalAchievements,
    completionPercentage: computedStats.completionPercentage,
    
    // Actions
    refresh: refreshData,
    unlockAchievement,
    
    // Status
    isReady: !loading && !error && achievements.length > 0
  };
};

// Default export
export default useAchievementManager;

// Ensure this file is treated as a module
export {};