/**
 * AuthManager - User-basierter Aufbau (kein Singleton)
 * Jede Instanz verwaltet einen spezifischen User-Kontext
 */

// ===== BACKEND-KOMPATIBLE TYPES (unverändert) =====

export interface User {
  id: number;
  username: string;
  email: string;
  displayName?: string;
  membershipTier: string;
  last_active?: string;
  created_at?: string;
}

export interface AuthResult {
  success: boolean;
  authorityLevel?: 'DEMO' | 'PRODUCTION' | 'ADMIN';
  user?: User;
  isAdmin?: boolean;
  token?: string;
  authority?: string;
  error?: string;
  message?: string;
}

export interface LoginCredentials {
  username: string;
  password: string;
  adminPassword?: string;
}

export interface CreateUserData {
  username: string;
  email: string;
  password: string;
  displayName?: string;
  authorityLevel?: 'PRODUCTION' | 'ADMIN';
}

export interface AuthState {
  currentUser: User | null;
  authToken: string | null;
  authorityLevel: 'DEMO' | 'PRODUCTION' | 'ADMIN';
  isAuthenticated: boolean;
  isLoading: boolean;
  error: string | null;
  isAdmin: boolean;
}

export type AuthorityLevel = 'DEMO' | 'PRODUCTION' | 'ADMIN';

// Legacy Types
export interface RegisterData {
  username: string;
  email: string;
  password: string;
}

export interface GameResult {
  gameType: string;
  score: number;
  additionalData?: Record<string, any>;
}

export interface AuthManagerStatus {
  isAuthenticated: boolean;
  currentUser: string | null;
  authorityLevel: AuthorityLevel;
  hasToken: boolean;
  baseUrl: string;
  userId: number | null;
  membershipTier: string | null;
  isAdmin: boolean;
}

type AuthEventCallback = (data: any) => void;

// ===== USER-BASIERTE AUTHMANAGER KLASSE =====

class AuthManager {
  private baseUrl: string;
  private apiPath: string;
  private currentUser: User | null = null;
  private authToken: string | null = null;
  private authorityLevel: AuthorityLevel = 'DEMO';
  private isAuthenticated: boolean = false;
  private eventListeners: Map<string, AuthEventCallback[]> = new Map();
  private instanceId: string;

  constructor(config?: {
    baseUrl?: string;
    apiPath?: string;
    instanceId?: string;
  }) {
    this.baseUrl = config?.baseUrl || process.env.REACT_APP_BACKEND_URL || 'http://localhost:3001';
    this.apiPath = config?.apiPath || '/api/auth';
    this.instanceId = config?.instanceId || `auth-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
    
    console.log(`[AuthManager-${this.instanceId}] Created new instance`);
    
    // Automatische Initialisierung
    this.initialize();
  }

  private async initialize(): Promise<void> {
    console.log(`[AuthManager-${this.instanceId}] Initializing...`);
    await this.checkExistingSession();
  }

  // ===================================================================
  // SESSION MANAGEMENT
  // ===================================================================

  async checkExistingSession(): Promise<boolean> {
    try {
      console.log(`[AuthManager-${this.instanceId}] Checking for existing session...`);
      console.log(`[AuthManager-${this.instanceId}] Full URL: ${this.baseUrl}${this.apiPath}/authority-info`);
      
      const response = await fetch(`${this.baseUrl}${this.apiPath}/authority-info`, {
        method: 'GET',
        credentials: 'include',
        headers: {
          'Content-Type': 'application/json'
        }
      });
      
      console.log(`[AuthManager-${this.instanceId}] Response status: ${response.status}, OK: ${response.ok}`);
      
      if (response.ok) {
        const data = await response.json();
        console.log(`[AuthManager-${this.instanceId}] Response data:`, data);
        
        if (data.success && data.user) {
          console.log(`[AuthManager-${this.instanceId}] Existing session found:`, data.user.username);
          
          this.currentUser = this.normalizeUser(data.user);
          this.authToken = data.token || null;
          this.authorityLevel = data.authorityLevel || data.authority || 'PRODUCTION';
          this.isAuthenticated = true;
  
          this.emit('sessionRestored', {
            user: this.currentUser,
            authority: this.authorityLevel,
            isAdmin: this.isAdmin()
          });
  
          return true;
        }
      } else if (response.status === 404) {
        console.log(`[AuthManager-${this.instanceId}] Authority-info endpoint not found - Backend route missing`);
        return false;
      }
    } catch (error) {
      console.error(`[AuthManager-${this.instanceId}] Session check failed:`, error);
    }
  
    return false;
  }

  // ===================================================================
  // AUTHENTICATION METHODS
  // ===================================================================

  async login(credentials: LoginCredentials): Promise<AuthResult> {
    try {
      console.log(`[AuthManager-${this.instanceId}] Authority Login - ${credentials.username} ${credentials.adminPassword ? '(mit Admin-PW)' : '(normal)'}`);
      
      const response = await fetch(`${this.baseUrl}${this.apiPath}/authority-login`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        credentials: 'include',
        body: JSON.stringify({
          username: credentials.username,
          password: credentials.password,
          adminPassword: credentials.adminPassword || undefined
        })
      });

      const data = await response.json();

      if (data.success) {
        this.currentUser = this.normalizeUser(data.user);
        this.authToken = data.token || null;
        this.authorityLevel = data.authorityLevel || 'PRODUCTION';
        this.isAuthenticated = true;

        console.log(`[AuthManager-${this.instanceId}] Authority Login erfolgreich - ${credentials.username} -> ${this.authorityLevel}`);
        
        this.emit('loginSuccess', {
          user: this.currentUser,
          token: this.authToken,
          authority: this.authorityLevel,
          isAdmin: this.isAdmin()
        });

        return {
          success: true,
          authorityLevel: this.authorityLevel,
          user: this.currentUser,
          isAdmin: this.isAdmin(),
          message: data.message || `Anmeldung erfolgreich - ${this.authorityLevel}`,
          token: this.authToken || undefined
        };
      } else {
        console.error(`[AuthManager-${this.instanceId}] Login failed:`, data.message);
        this.emit('loginError', data.message || 'Login failed');
        
        return {
          success: false,
          authorityLevel: 'DEMO',
          error: data.message || 'Login failed'
        };
      }

    } catch (error) {
      console.error(`[AuthManager-${this.instanceId}] Login error:`, error);
      this.emit('loginError', 'Connection error');
      return {
        success: false,
        authorityLevel: 'DEMO',
        error: 'Connection error to server'
      };
    }
  }

  async register(userData: CreateUserData): Promise<AuthResult> {
    try {
      console.log(`[AuthManager-${this.instanceId}] Creating user:`, userData.username);
      
      const response = await fetch(`${this.baseUrl}${this.apiPath}/register`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        credentials: 'include',
        body: JSON.stringify({
          username: userData.username,
          email: userData.email,
          password: userData.password,
          displayName: userData.displayName || userData.username,
          authorityLevel: userData.authorityLevel || 'PRODUCTION'
        })
      });

      const data = await response.json();

      if (data.success) {
        console.log(`[AuthManager-${this.instanceId}] Registration successful`);
        this.emit('registerSuccess', data);
        
        return {
          success: true,
          message: 'Registration successful'
        };
      } else {
        console.error(`[AuthManager-${this.instanceId}] Registration failed:`, data.message);
        this.emit('registerError', data.message);
        
        return {
          success: false,
          error: data.message || 'Registration failed'
        };
      }

    } catch (error) {
      console.error(`[AuthManager-${this.instanceId}] Registration error:`, error);
      this.emit('registerError', 'Connection error');
      
      return {
        success: false,
        error: 'Connection error to server'
      };
    }
  }

  async logout(): Promise<void> {
    try {
      console.log(`[AuthManager-${this.instanceId}] Logging out...`);
      
      const response = await fetch(`${this.baseUrl}${this.apiPath}/logout`, {
        method: 'POST',
        credentials: 'include'
      });

      if (response.ok) {
        console.log(`[AuthManager-${this.instanceId}] Backend logout successful`);
      }
    } catch (error) {
      console.error(`[AuthManager-${this.instanceId}] Logout error:`, error);
    } finally {
      this.currentUser = null;
      this.authToken = null;
      this.authorityLevel = 'DEMO';
      this.isAuthenticated = false;

      console.log(`[AuthManager-${this.instanceId}] Logged out - switched to DEMO mode`);
      this.emit('logoutSuccess', undefined);
    }
  }

  // ===================================================================
  // BACKEND-KOMPATIBLE METHODEN
  // ===================================================================

  async authenticateUser(username: string, password: string): Promise<User | null> {
    try {
      const result = await this.login({ username, password });
      return result.success && result.user ? result.user : null;
    } catch (error) {
      console.error(`[AuthManager-${this.instanceId}] Authentication error:`, error);
      return null;
    }
  }

  async getUser(identifier: string): Promise<User | null> {
    try {
      const response = await fetch(`${this.baseUrl}${this.apiPath}/user/${encodeURIComponent(identifier)}`, {
        method: 'GET',
        credentials: 'include',
        headers: {
          'Authorization': this.authToken ? `Bearer ${this.authToken}` : ''
        }
      });

      if (response.ok) {
        const data = await response.json();
        if (data.success && data.user) {
          return this.normalizeUser(data.user);
        }
      }
      return null;
    } catch (error) {
      console.error(`[AuthManager-${this.instanceId}] Get user error:`, error);
      return null;
    }
  }

  // ===================================================================
  // USER DATA MANAGEMENT
  // ===================================================================

  private normalizeUser(backendUser: any): User {
    return {
      id: typeof backendUser.id === 'string' ? parseInt(backendUser.id) : backendUser.id,
      username: backendUser.username,
      email: backendUser.email,
      displayName: backendUser.displayName || backendUser.display_name,
      membershipTier: backendUser.membershipTier || backendUser.membership_tier || 'basic',
      last_active: backendUser.last_active,
      created_at: backendUser.created_at
    };
  }

  // ===================================================================
  // GETTERS
  // ===================================================================

  getCurrentUser(): User | null {
    return this.currentUser;
  }

  getAuthToken(): string | null {
    return this.authToken;
  }

  getAuthorityLevel(): AuthorityLevel {
    return this.authorityLevel;
  }

  isLoggedIn(): boolean {
    return this.isAuthenticated && this.currentUser !== null;
  }

  isAdmin(): boolean {
    return this.authorityLevel === 'ADMIN';
  }

  isProduction(): boolean {
    return this.authorityLevel === 'PRODUCTION';
  }

  isDemo(): boolean {
    return this.authorityLevel === 'DEMO';
  }

  getInstanceId(): string {
    return this.instanceId;
  }

  // ===================================================================
  // EVENT SYSTEM
  // ===================================================================

  on(event: string, callback: AuthEventCallback): void {
    if (!this.eventListeners.has(event)) {
      this.eventListeners.set(event, []);
    }
    this.eventListeners.get(event)!.push(callback);
  }

  off(event: string, callback: AuthEventCallback): void {
    if (this.eventListeners.has(event)) {
      const listeners = this.eventListeners.get(event)!;
      const index = listeners.indexOf(callback);
      if (index > -1) {
        listeners.splice(index, 1);
      }
    }
  }

  private emit(event: string, data: any): void {
    if (this.eventListeners.has(event)) {
      this.eventListeners.get(event)!.forEach(callback => {
        try {
          callback(data);
        } catch (error) {
          console.error(`[AuthManager-${this.instanceId}] Error in event listener for ${event}:`, error);
        }
      });
    }
  }

  // ===================================================================
  // STATUS & DEBUG
  // ===================================================================

  getStatus(): AuthManagerStatus {
    return {
      isAuthenticated: this.isAuthenticated,
      currentUser: this.currentUser?.username || null,
      authorityLevel: this.authorityLevel,
      hasToken: !!this.authToken,
      baseUrl: this.baseUrl,
      userId: this.currentUser?.id || null,
      membershipTier: this.currentUser?.membershipTier || null,
      isAdmin: this.isAdmin()
    };
  }

  getDebugStatus(): {
    instanceId: string;
    authorityLevel: AuthorityLevel;
    isProduction: boolean;
    isAdmin: boolean;
    isAuthenticated: boolean;
    hasUser: boolean;
    backendUrl: string;
  } {
    return {
      instanceId: this.instanceId,
      authorityLevel: this.authorityLevel,
      isProduction: this.isProduction(),
      isAdmin: this.isAdmin(),
      isAuthenticated: this.isAuthenticated,
      hasUser: !!this.currentUser,
      backendUrl: this.baseUrl
    };
  }

  // ===================================================================
  // LEGACY METHODS (für Kompatibilität)
  // ===================================================================

  createGuestUser(): User {
    this.currentUser = {
      id: Math.floor(Math.random() * 1000000),
      username: 'Guest Player',
      email: 'guest@retro.game',
      displayName: 'Guest Player',
      membershipTier: 'basic',
      created_at: new Date().toISOString()
    };

    this.isAuthenticated = true;
    this.authorityLevel = 'DEMO';

    console.log(`[AuthManager-${this.instanceId}] Guest user created`);
    this.emit('loginSuccess', {
      user: this.currentUser,
      authority: this.authorityLevel,
      isGuest: true
    });

    return this.currentUser;
  }

  async updateStats(gameType: string, score: number): Promise<boolean> {
    console.warn(`[AuthManager-${this.instanceId}] updateStats deprecated - use backend user stats`);
    return false;
  }

  async updateHighScore(gameType: string, score: number): Promise<boolean> {
    console.warn(`[AuthManager-${this.instanceId}] updateHighScore deprecated - use backend user stats`);
    return false;
  }
}

// ===== FACTORY FUNCTION STATT SINGLETON =====

export const createAuthManager = (config?: {
  baseUrl?: string;
  apiPath?: string;
  instanceId?: string;
}): AuthManager => {
  return new AuthManager(config);
};

export default AuthManager;