import React from 'react';
import styled from 'styled-components';
import { retroTheme } from './theme';

interface ZoneContainerProps {
  children: React.ReactNode;
  className?: string;
}

const Container = styled.div`
  min-height: 100vh;
  background: linear-gradient(135deg, ${retroTheme.colors.primary} 0%, ${retroTheme.colors.secondary} 100%);
  color: ${retroTheme.colors.textPrimary};
  font-family: ${retroTheme.fonts.primary};
  padding: ${retroTheme.spacing.lg};
  position: relative;

  &::before {
    content: '';
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: 
      radial-gradient(circle at 20% 80%, rgba(0, 255, 0, 0.1) 0%, transparent 50%),
      radial-gradient(circle at 80% 20%, rgba(0, 255, 255, 0.1) 0%, transparent 50%);
    pointer-events: none;
    z-index: -1;
  }
`;

export const ZoneContainer: React.FC<ZoneContainerProps> = ({ children, className }) => (
  <Container className={className}>
    {children}
  </Container>
);