/**
 * useAuth Hook - TypeScript Conversion
 * Path: frontend/src/managers/AuthManager/hooks/useAuth.ts
 * 
 * React Hook for Frontend AuthManager Integration
 * Converted from JavaScript to TypeScript
 */

import { useState, useEffect, useRef } from 'react';
import { createAuthManager } from '../AuthManager';
import type {
  User,
  AuthorityLevel,
  LoginCredentials,
  RegisterData,
  AuthResult,
  GameResult,
  AuthManagerStatus
} from '../AuthManager';

// Hook state interface
interface AuthState {
  currentUser: User | null;
  authToken: string | null;
  authorityLevel: AuthorityLevel;
  isAuthenticated: boolean;
  isLoading: boolean;
  error: string | null;
  isGuest: boolean;
}

// Hook return type
interface UseAuthReturn {
  // State
  currentUser: User | null;
  authToken: string | null;
  authorityLevel: AuthorityLevel;
  isAuthenticated: boolean;
  isLoading: boolean;
  error: string | null;
  isGuest: boolean;

  // Computed
  isLoggedIn: boolean;
  isAdmin: boolean;
  isDevelopment: boolean;

  // Auth Functions
  login: (credentials: LoginCredentials) => Promise<AuthResult>;
  register: (userData: RegisterData) => Promise<AuthResult>;
  logout: () => Promise<void>;
  loginAsGuest: () => AuthResult;
  checkSession: () => Promise<boolean>;
  clearError: () => void;

  // Game Integration
  updateStats: (gameType: string, score: number) => Promise<boolean>;
  updateHighScore: (gameType: string, score: number) => Promise<boolean>;
  recordGameResult: (gameType: string, score: number, additionalData?: Record<string, any>) => Promise<{ newHighScore: boolean }>;

  // Utility
  getManagerStatus: () => AuthManagerStatus;

  // Legacy support for existing code
  user: User | null; // Alias
  onlineUsers: number; // Placeholder - will be taken over by SessionManager
}

// Game Integration Hook return type
interface UseGameIntegrationReturn {
  currentUser: User | null;
  isLoggedIn: boolean;
  recordGameResult: (gameType: string, score: number, additionalData?: Record<string, any>) => Promise<{ newHighScore: boolean }>;
}

export const useAuth = (): UseAuthReturn => {
  const authManager = useRef<ReturnType<typeof createAuthManager> | null>(null);
  
  const [state, setState] = useState<AuthState>({
    currentUser: null,
    authToken: null,
    authorityLevel: 'DEMO',
    isAuthenticated: false,
    isLoading: true,
    error: null,
    isGuest: false
  });

  // Event Handlers
  useEffect(() => {
    // Nur einmal erstellen
    if (!authManager.current) {
      authManager.current = createAuthManager();
    }
  
    const manager = authManager.current;

    // Event handler definitions
    const handleSessionRestored = (data: { user: User; authority: AuthorityLevel }) => {
      console.log('[useAuth] Session restored:', data.user.username);
      setState(prev => ({
        ...prev,
        currentUser: data.user,
        authorityLevel: data.authority,
        isAuthenticated: true,
        isLoading: false,
        error: null
      }));
    };

    const handleLoginSuccess = (data: { user: User; token?: string; authority: AuthorityLevel; isGuest?: boolean }) => {
      console.log('[useAuth] Login successful:', data.user.username);
      setState(prev => ({
        ...prev,
        currentUser: data.user,
        authToken: data.token || null,
        authorityLevel: data.authority,
        isAuthenticated: true,
        isLoading: false,
        error: null,
        isGuest: data.isGuest || false
      }));
    };

    const handleLoginError = (error: string) => {
      console.error('[useAuth] Login error:', error);
      setState(prev => ({
        ...prev,
        error,
        isLoading: false,
        isAuthenticated: false
      }));
    };

    const handleLogoutSuccess = () => {
      console.log('[useAuth] Logout successful');
      setState(prev => ({
        ...prev,
        currentUser: null,
        authToken: null,
        authorityLevel: 'DEMO',
        isAuthenticated: false,
        isLoading: false,
        error: null,
        isGuest: false
      }));
    };

    const handleRegisterSuccess = (data: any) => {
      console.log('[useAuth] Registration successful');
      setState(prev => ({
        ...prev,
        error: null,
        isLoading: false
      }));
    };

    const handleRegisterError = (error: string) => {
      console.error('[useAuth] Registration error:', error);
      setState(prev => ({
        ...prev,
        error,
        isLoading: false
      }));
    };

    const handleStatsUpdated = (data: any) => {
      console.log('[useAuth] Stats updated:', data);
      // Trigger re-render through setState
      setState(prev => ({
        ...prev,
        currentUser: prev.currentUser ? { ...prev.currentUser } : null
      }));
    };

    const handleHighScoreUpdated = (data: any) => {
      console.log('[useAuth] High score updated:', data);
      // Trigger re-render through setState
      setState(prev => ({
        ...prev,
        currentUser: prev.currentUser ? { ...prev.currentUser } : null
      }));
    };

    // Register event listeners
    manager.on('sessionRestored', handleSessionRestored);
    manager.on('loginSuccess', handleLoginSuccess);
    manager.on('loginError', handleLoginError);
    manager.on('logoutSuccess', handleLogoutSuccess);
    manager.on('registerSuccess', handleRegisterSuccess);
    manager.on('registerError', handleRegisterError);
    manager.on('statsUpdated', handleStatsUpdated);
    manager.on('highScoreUpdated', handleHighScoreUpdated);

    // Initial State Setup
    const initialState: AuthState = {
      currentUser: manager.getCurrentUser(),
      authToken: manager.getAuthToken(),
      authorityLevel: manager.getAuthorityLevel(),
      isAuthenticated: manager.isLoggedIn(),
      isLoading: false, // Manager is already initialized
      error: null,
      isGuest: false
    };

    setState(initialState);

    // Cleanup
    return () => {
      manager.off('sessionRestored', handleSessionRestored);
      manager.off('loginSuccess', handleLoginSuccess);
      manager.off('loginError', handleLoginError);
      manager.off('logoutSuccess', handleLogoutSuccess);
      manager.off('registerSuccess', handleRegisterSuccess);
      manager.off('registerError', handleRegisterError);
      manager.off('statsUpdated', handleStatsUpdated);
      manager.off('highScoreUpdated', handleHighScoreUpdated);
    };
  }, []);

  // ===================================================================
  // AUTH FUNCTIONS
  // ===================================================================

  const login = async (credentials: LoginCredentials): Promise<AuthResult> => {
    setState(prev => ({ ...prev, isLoading: true, error: null }));
    
    try {
      const result = await authManager.current!.login(credentials);
      return result;
    } catch (error) {
      console.error('[useAuth] Login error:', error);
      setState(prev => ({ 
        ...prev, 
        isLoading: false, 
        error: 'Login failed' 
      }));
      return { success: false, error: 'Login failed' };
    }
  };

  const register = async (userData: RegisterData): Promise<AuthResult> => {
    setState(prev => ({ ...prev, isLoading: true, error: null }));
    
    try {
      const result = await authManager.current!.register(userData);
      return result;
    } catch (error) {
      console.error('[useAuth] Registration error:', error);
      setState(prev => ({ 
        ...prev, 
        isLoading: false, 
        error: 'Registration failed' 
      }));
      return { success: false, error: 'Registration failed' };
    }
  };

  const logout = async (): Promise<void> => {
    setState(prev => ({ ...prev, isLoading: true }));
    
    try {
      await authManager.current!.logout();
    } catch (error) {
      console.error('[useAuth] Logout error:', error);
      // Logout should always be successful (local cleanup)
    }
  };

  const loginAsGuest = (): AuthResult => {
    if (!authManager.current) {
      return { success: false, error: 'AuthManager not initialized' };
    }
    
    setState(prev => ({ ...prev, isLoading: true, error: null }));
    
    try {
      const guestUser = authManager.current.createGuestUser();
      return { success: true, user: guestUser };
    } catch (error) {
      console.error('[useAuth] Guest login error:', error);
      setState(prev => ({ 
        ...prev, 
        isLoading: false, 
        error: 'Guest login failed' 
      }));
      return { success: false, error: 'Guest login failed' };
    }
  };

  // ===================================================================
  // GAME INTEGRATION FUNCTIONS
  // ===================================================================

  const updateStats = async (gameType: string, score: number): Promise<boolean> => {
    if (!state.isAuthenticated || !authManager.current) {
      console.warn('[useAuth] Not authenticated or AuthManager not initialized - stats not updated');
      return false;
    }
  
    try {
      return await authManager.current.updateStats(gameType, score);
    } catch (error) {
      console.error('[useAuth] Stats update error:', error);
      return false;
    }
  };

  const updateHighScore = async (gameType: string, score: number): Promise<boolean> => {
    if (!state.isAuthenticated || !authManager.current) {
      console.warn('[useAuth] Not authenticated or AuthManager not initialized - high score not updated');
      return false;
    }
  
    try {
      return await authManager.current.updateHighScore(gameType, score);
    } catch (error) {
      console.error('[useAuth] High score update error:', error);
      return false;
    }
  }; 

  const recordGameResult = async (
    gameType: string, 
    score: number, 
    additionalData?: Record<string, any>
  ): Promise<{ newHighScore: boolean }> => {
    if (!state.isAuthenticated) {
      console.warn('[useAuth] Not authenticated - game result not recorded');
      return { newHighScore: false };
    }

    console.log(`[useAuth] Recording game result: ${gameType} = ${score}`);

    try {
      // Update stats
      await updateStats(gameType, score);
      
      // Check and update high score
      const newHighScore = await updateHighScore(gameType, score);

      if (additionalData) {
        console.log(`[useAuth] Additional game data for ${gameType}:`, additionalData);
      }

      return { newHighScore };
    } catch (error) {
      console.error('[useAuth] Game result recording error:', error);
      return { newHighScore: false };
    }
  };

  // ===================================================================
  // UTILITY FUNCTIONS
  // ===================================================================

  const checkSession = async (): Promise<boolean> => {
    if (!authManager.current) {
      console.error('[useAuth] AuthManager not initialized for session check');
      return false;
    }
    
    setState(prev => ({ ...prev, isLoading: true }));
    
    try {
      const hasSession = await authManager.current.checkExistingSession();
      return hasSession;
    } catch (error) {
      console.error('[useAuth] Session check error:', error);
      setState(prev => ({ 
        ...prev, 
        isLoading: false, 
        error: 'Session check failed' 
      }));
      return false;
    }
  };

  const clearError = (): void => {
    setState(prev => ({ ...prev, error: null }));
  };

  const getManagerStatus = (): AuthManagerStatus => {
    if (!authManager.current) {
      return {
        isAuthenticated: false,
        currentUser: null,
        authorityLevel: 'DEMO',
        hasToken: false,
        baseUrl: '',
        userId: null,
        membershipTier: null,
        isAdmin: false
      };
    }
    
    return authManager.current.getStatus();
  }; 

  // ===================================================================
  // COMPUTED VALUES
  // ===================================================================

  const isAdmin = state.authorityLevel === 'ADMIN';
  const isDevelopment = state.authorityLevel === 'ADMIN';

  // ===================================================================
  // RETURN OBJECT
  // ===================================================================

  return {
    // State
    currentUser: state.currentUser,
    authToken: state.authToken,
    authorityLevel: state.authorityLevel,
    isAuthenticated: state.isAuthenticated,
    isLoading: state.isLoading,
    error: state.error,
    isGuest: state.isGuest,

    // Computed
    isLoggedIn: state.isAuthenticated,
    isAdmin,
    isDevelopment,

    // Auth Functions
    login,
    register,
    logout,
    loginAsGuest,
    checkSession,
    clearError,

    // Game Integration
    updateStats,
    updateHighScore,
    recordGameResult,

    // Utility
    getManagerStatus,

    // Legacy support for existing code
    user: state.currentUser, // Alias
    onlineUsers: 0 // Placeholder - will be taken over by SessionManager
  };
};

// ===================================================================
// GAME INTEGRATION HOOK (Legacy Support)
// ===================================================================

export const useGameIntegration = (): UseGameIntegrationReturn => {
  const { currentUser, isAuthenticated, recordGameResult } = useAuth();

  return {
    currentUser,
    isLoggedIn: isAuthenticated,
    recordGameResult
  };
};

// Default Export
export default useAuth;