import React from 'react';
import ReactDOM from 'react-dom/client';
import { Elements } from '@stripe/react-stripe-js';
import { loadStripe } from '@stripe/stripe-js';
import App from './App';
import './index.css';

const stripePromise = loadStripe(process.env.REACT_APP_STRIPE_PUBLISHABLE_KEY);

const isDemoMode = process.env.REACT_APP_DEMO_MODE === 'true';
console.log(`🎭 Frontend starting in ${isDemoMode ? 'DEMO' : 'PRODUCTION'} mode`);

const root = ReactDOM.createRoot(
  document.getElementById('root')
);

root.render(
  <React.StrictMode>
    <Elements stripe={stripePromise}>
      <App />
    </Elements>
  </React.StrictMode>
);

if (isDemoMode) {
  console.log('🎭 Demo Mode Features:');
  console.log('   ✅ Mock payment processing');
  console.log('   ✅ Test card numbers work');
  console.log('   ✅ No real charges');
  console.log('   ✅ Full UI testing');
  console.log('   💳 Test Card: 4242 4242 4242 4242');
}

console.log('🎮 Retro Gaming Service initialized successfully!');