/**
 * AchievementManager - Frontend API Client
 * Path: FRONTEND\src\managers\AchievmentManager\AchievmentManager.ts
 * 
 * API Client for Backend AchievementManager
 * Consumes Backend-First data structures 1:1
 */
import type { 
  UserAchievements, 
  UserProgress, 
  Leaderboard, 
  UserStatistics, 
  UnlockResult,
  ScoreViewData,
  ScoreViewAchievement,
  ScoreViewLeaderboardEntry,
  ScoreViewUserStats,
  ApiResponse
} from './types';

interface CacheEntry {
  data: any;
  expiry: number;
}

class AchievementManager {
  private baseURL: string;
  private apiPath: string;
  private isInitialized: boolean;
  private cache: Map<string, CacheEntry>;
  private cacheTimeout: number;

  constructor() {
    this.baseURL = process.env.REACT_APP_API_URL || 'http://localhost:3001';
    this.apiPath = '/api';
    this.isInitialized = false;
    this.cache = new Map<string, CacheEntry>();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes
  }

  /**
   * Initialize Frontend AchievementManager
   */
  initialize(): void {
    if (this.isInitialized) {
      console.log('AchievementManager: Already initialized');
      return;
    }

    this.isInitialized = true;
    console.log('AchievementManager: Initialized successfully');
  }

  /**
   * Get user achievements from backend
   * Consumes: Backend AchievementManager.getUserAchievements()
   */
  async getUserAchievements(userId: string): Promise<UserAchievements> {
    if (!userId) {
      throw new Error('User ID is required');
    }

    const cacheKey = `achievements_${userId}`;
    const cachedData = this.getFromCache(cacheKey);
    if (cachedData) {
      return cachedData as UserAchievements;
    }

    const response = await this.makeRequest<UserAchievements>('GET', `/api/achievements/user/${userId}`);
    
    if (!response.success) {
      throw new Error(response.error || 'Failed to get user achievements');
    }

    const achievementsData: UserAchievements = {
      achievements: response.data?.achievements || [],
      unlocked_count: response.data?.unlocked_count || 0,
      total_count: response.data?.total_count || 0,
      recent_unlocks: response.data?.recent_unlocks || [],
      completion_percentage: response.data?.completion_percentage || 0,
      last_updated: response.data?.last_updated || new Date().toISOString()
    };

    this.setCache(cacheKey, achievementsData);
    return achievementsData;
  }

  /**
   * Get user progress from backend
   * Consumes: Backend AchievementManager.getUserProgress()
   */
  async getUserProgress(userId: string): Promise<UserProgress> {
    if (!userId) {
      throw new Error('User ID is required');
    }

    const cacheKey = `progress_${userId}`;
    const cachedData = this.getFromCache(cacheKey);
    if (cachedData) {
      return cachedData as UserProgress;
    }

    const response = await this.makeRequest<UserProgress>('GET', `/user/progress?userId=${userId}`);
    
    if (!response.success) {
      throw new Error(response.error || 'Failed to get user progress');
    }

    const progressData: UserProgress = {
      user_id: response.data?.user_id || userId,
      games_played: response.data?.games_played || 0,
      total_score: response.data?.total_score || 0,
      hours_played: response.data?.hours_played || 0,
      achievements_unlocked: response.data?.achievements_unlocked || 0,
      current_streak: response.data?.current_streak || 0,
      best_scores: response.data?.best_scores || [],
      level: response.data?.level || 1,
      experience_points: response.data?.experience_points || 0,
      last_played: response.data?.last_played || null,
      favorite_game: response.data?.favorite_game || null,
      statistics: response.data?.statistics || {}
    };

    this.setCache(cacheKey, progressData);
    return progressData;
  }

  /**
   * Get leaderboard from backend
   * Consumes: Backend AchievementManager.getLeaderboard()
   */
  async getLeaderboard(gameId: string | null = null, limit: number = 50): Promise<Leaderboard> {
    const cacheKey = `leaderboard_${gameId || 'global'}_${limit}`;
    const cachedData = this.getFromCache(cacheKey);
    if (cachedData) {
      return cachedData as Leaderboard;
    }

    let endpoint = `/leaderboard?limit=${limit}`;
    if (gameId) {
      endpoint += `&gameId=${gameId}`;
    }

    const response = await this.makeRequest<Leaderboard>('GET', endpoint);
    
    if (!response.success) {
      throw new Error(response.error || 'Failed to get leaderboard');
    }

    const leaderboardData: Leaderboard = {
      entries: response.data?.entries || [],
      total_players: response.data?.total_players || 0,
      game_filter: response.data?.game_filter || null,
      last_updated: response.data?.last_updated || new Date().toISOString(),
      page_size: response.data?.page_size || limit
    };

    this.setCache(cacheKey, leaderboardData, 2 * 60 * 1000); // 2 minutes cache for leaderboard
    return leaderboardData;
  }

  /**
   * Get user statistics from backend
   * Consumes: Backend AchievementManager.getUserStatistics()
   */
  async getUserStatistics(userId: string): Promise<UserStatistics> {
    if (!userId) {
      throw new Error('User ID is required');
    }

    const cacheKey = `statistics_${userId}`;
    const cachedData = this.getFromCache(cacheKey);
    if (cachedData) {
      return cachedData as UserStatistics;
    }

    const response = await this.makeRequest<UserStatistics>('GET', `/user/statistics?userId=${userId}`);
    
    if (!response.success) {
      throw new Error(response.error || 'Failed to get user statistics');
    }

    const statisticsData: UserStatistics = {
      user_id: response.data?.user_id || userId,
      games_played: response.data?.games_played || 0,
      total_score: response.data?.total_score || 0,
      achievements_unlocked: response.data?.achievements_unlocked || 0,
      hours_played: response.data?.hours_played || 0,
      global_rank: response.data?.global_rank || null,
      level: response.data?.level || 1,
      experience_points: response.data?.experience_points || 0,
      completion_percentage: response.data?.completion_percentage || 0,
      daily_stats: response.data?.daily_stats || [],
      weekly_summary: response.data?.weekly_summary || {},
      achievements_progress: response.data?.achievements_progress || [],
      average_score: response.data?.average_score || 0,
      best_streak: response.data?.best_streak || 0,
      current_streak: response.data?.current_streak || 0,
      last_updated: response.data?.last_updated || new Date().toISOString()
    };

    this.setCache(cacheKey, statisticsData);
    return statisticsData;
  }

  /**
   * Unlock achievement via backend
   * Consumes: Backend AchievementManager.unlockAchievement()
   */
  async unlockAchievement(userId: string, achievementId: string, gameContext: any = {}): Promise<UnlockResult> {
    if (!userId || !achievementId) {
      throw new Error('User ID and Achievement ID are required');
    }

    const response = await this.makeRequest<UnlockResult>('POST', '/achievements/unlock', {
      userId: userId,
      achievementId: achievementId,
      gameContext: gameContext
    });

    if (!response.success) {
      throw new Error(response.error || 'Failed to unlock achievement');
    }

    // Clear cache for user achievements and statistics
    this.clearUserCache(userId);

    return {
      success: response.data?.success || false,
      message: response.data?.message || '',
      achievement: response.data?.achievement || {} as any
    };
  }

  /**
   * Get formatted data for ScoreView component
   * Transforms backend data for frontend component consumption
   */
  async getScoreViewData(userId: string): Promise<ScoreViewData> {
    try {
      // Parallel data fetching
      const [achievements, progress, leaderboard, statistics] = await Promise.all([
        this.getUserAchievements(userId),
        this.getUserProgress(userId),
        this.getLeaderboard(null, 20),
        this.getUserStatistics(userId)
      ]);

      // Transform backend data for ScoreView.tsx consumption
      return {
        // Achievements data (matches ScoreView Achievement interface)
        achievements: achievements.achievements.map(achievement => ({
          id: achievement.id,
          title: achievement.title,
          description: achievement.description,
          icon: achievement.icon,
          unlocked: achievement.unlocked,
          unlockedAt: achievement.unlocked_at
        })),

        // Leaderboard data (matches ScoreView LeaderboardEntry interface)  
        leaderboard: leaderboard.entries.map(entry => ({
          rank: entry.rank,
          player: entry.username,
          score: entry.score,
          game: entry.game_name,
          isCurrentUser: entry.user_id === userId
        })),

        // User stats (matches ScoreView UserStats interface)
        userStats: {
          gamesPlayed: statistics.games_played,
          totalScore: statistics.total_score,
          achievementsUnlocked: statistics.achievements_unlocked,
          hoursPlayed: statistics.hours_played
        },

        // Additional metadata
        metadata: {
          completionPercentage: achievements.completion_percentage,
          globalRank: statistics.global_rank,
          level: statistics.level,
          lastUpdated: new Date().toISOString()
        }
      };

    } catch (error) {
      console.error('AchievementManager: Get ScoreView data failed:', error);
      
      // Return fallback data structure matching ScoreView requirements
      return {
        achievements: [],
        leaderboard: [],
        userStats: {
          gamesPlayed: 0,
          totalScore: 0,
          achievementsUnlocked: 0,
          hoursPlayed: 0
        },
        metadata: {
          completionPercentage: 0,
          globalRank: null,
          level: 1,
          lastUpdated: new Date().toISOString(),
          error: error instanceof Error ? error.message : 'Unknown error'
        }
      };
    }
  }

  /**
   * HTTP Request helper
   */
  private async makeRequest<T>(method: string, endpoint: string, data: any = null): Promise<ApiResponse<T>> {
    const url = `${this.baseURL}${this.apiPath}${endpoint}`;
    
    const options: RequestInit = {
      method: method,
      headers: {
        'Content-Type': 'application/json',
      }
    };

    if (data) {
      options.body = JSON.stringify(data);
    }

    const response = await fetch(url, options);
    
    if (!response.ok) {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }

    return await response.json();
  }

  /**
   * Cache management
   */
  private setCache(key: string, data: any, timeout: number | null = null): void {
    const expiry = Date.now() + (timeout || this.cacheTimeout);
    this.cache.set(key, { data, expiry });
  }

  private getFromCache(key: string): any | null {
    const cached = this.cache.get(key);
    if (!cached) return null;
    
    if (Date.now() > cached.expiry) {
      this.cache.delete(key);
      return null;
    }
    
    return cached.data;
  }

  clearCache(): void {
    this.cache.clear();
  }

  private clearUserCache(userId: string): void {
    const keys = Array.from(this.cache.keys());
    keys.forEach(key => {
      if (key.includes(userId)) {
        this.cache.delete(key);
      }
    });
  }

  /**
   * Health check
   */
  async healthCheck(): Promise<boolean> {
    try {
      const response = await this.makeRequest<any>('GET', '/health');
      return response.success;
    } catch (error) {
      console.error('AchievementManager: Health check failed:', error);
      return false;
    }
  }
}

// Export class and singleton instance
export { AchievementManager };

const achievementManager = new AchievementManager();
export default achievementManager;