// ==========================================
// SingleplayerZone.tsx  
// ==========================================
import React from 'react';
import { useNavigate } from 'react-router-dom';
import styled, { keyframes } from 'styled-components';

// ✅ NUR die verfügbaren shared components
import {
  ZoneContainer,
  ZoneTitle,
  RetroButton,
  RetroCard,
  retroTheme
} from '../../../shared/ui';

// Game Data Interface
interface GameData {
  id: string;
  title: string;
  icon: string;
  route: string;
  enabled: boolean;
  description: string;
  difficulty: 'easy' | 'medium' | 'hard';
  requiresProduction?: boolean;
}

// ==========================================
// LOKALE STYLED COMPONENTS (bis shared fertig ist)
// ==========================================

const ZoneHeader = styled.div`
  text-align: center;
  margin: 3rem 0 1rem 0;
`;

// NEON ANIMATIONS
const neonFlicker = keyframes`
  0%, 100% {
    text-shadow: 
      0 0 5px #ff00ff,
      0 0 10px #ff00ff,
      0 0 20px #ff00ff,
      0 0 40px #ff00ff,
      0 0 80px #ff00ff;
  }
  50% {
    text-shadow: 
      0 0 2px #ff00ff,
      0 0 5px #ff00ff,
      0 0 10px #ff00ff,
      0 0 20px #ff00ff,
      0 0 40px #ff00ff;
  }
`;

const neonPulse = keyframes`
  0% {
    text-shadow: 
      0 0 10px #00ffff,
      0 0 20px #00ffff,
      0 0 30px #00ffff,
      0 0 40px #00ffff,
      0 0 70px #00ffff,
      0 0 80px #00ffff,
      0 0 100px #00ffff;
    color: #ffffff;
  }
  50% {
    text-shadow: 
      0 0 5px #ff00ff,
      0 0 10px #ff00ff,
      0 0 15px #ff00ff,
      0 0 20px #ff00ff,
      0 0 35px #ff00ff,
      0 0 40px #ff00ff,
      0 0 50px #ff00ff;
    color: #ff00ff;
  }
  100% {
    text-shadow: 
      0 0 10px #00ffff,
      0 0 20px #00ffff,
      0 0 30px #00ffff,
      0 0 40px #00ffff,
      0 0 70px #00ffff,
      0 0 80px #00ffff,
      0 0 100px #00ffff;
    color: #ffffff;
  }
`;

// GROßER TITEL mit echtem NEON EFFEKT
const BigTitle = styled.h1`
  font-size: 5rem;
  font-weight: 900;
  background: linear-gradient(45deg, #00ffff, #ff00ff, #00ffff);
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  margin: 0 0 2rem 0;
  text-align: center;
  position: relative;
  
  /* Hauptneon-Effekt */
  animation: ${neonPulse} 6s ease-in-out infinite;
  
  /* Zusätzlicher Glow-Effekt */
  &::before {
    content: 'SINGLEPLAYER';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    z-index: -1;
    text-shadow: 
      0 0 20px #00ffff,
      0 0 40px #ff00ff,
      0 0 60px #00ffff,
      0 0 80px #ff00ff;
    animation: ${neonFlicker} 4s linear infinite;
  }
  
  /* Border-Glow */
  filter: drop-shadow(0 0 20px #00ffff) drop-shadow(0 0 40px #ff00ff);

  @media (max-width: 768px) {
    font-size: 3rem;
    letter-spacing: 0.15em;
    
    &::before {
      content: 'SINGLEPLAYER';
    }
  }
`;

const GamesGrid = styled.div`
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 1.5rem;
  max-width: 830px;
  margin: 4rem auto 4rem auto;
  flex-wrap: nowrap;
  
  @media (max-width: 768px) {
    flex-direction: column;
    gap: 1rem;
  }
`;

const GameCard = styled.button`
  background: rgba(0, 20, 40, 0.8);
  border: 3px solid #00ff00;
  border-radius: 12px;
  padding: 1.5rem 1.8rem;
  cursor: pointer;
  transition: all 0.3s ease;
  width: 200px;
  height: 110px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 0.6rem;

  &:hover {
    transform: scale(1.05);
    box-shadow: 0 0 25px #00ff00aa;
    
    .title {
      text-shadow: 0 0 15px #00ff00, 0 0 25px #00ff00aa;
    }
    
    .icon {
      filter: drop-shadow(0 0 12px #00ff00);
    }
  }
`;

const GameIcon = styled.div`
  font-size: 2.5rem;
  margin: 0;
  transition: all 0.3s ease;
`;

const GameTitle = styled.h3`
  color: #00ff00;
  font-size: 1.1rem;
  font-weight: bold;
  margin: 0;
  text-transform: uppercase;
  letter-spacing: 0.1rem;
  transition: all 0.3s ease;
  text-shadow: 0 0 10px #00ff00, 0 0 20px #00ff00aa;
`;

// KLEINERES Grid für Premium Games
const PremiumGrid = styled.div`
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 1.5rem;
  max-width: 700px;
  margin: 0 auto;
  flex-wrap: wrap;
  
  @media (max-width: 768px) {
    flex-direction: column;
    gap: 1rem;
  }
`;

const diagonalSweep = keyframes`
  0% {
    transform: translateX(-100%) translateY(-100%);
  }
  100% {
    transform: translateX(100%) translateY(100%);
  }
`;

const PremiumCard = styled.button`
  background: linear-gradient(135deg, rgba(0, 20, 40, 0.3) 0%, rgba(40, 40, 60, 0.2) 50%, rgba(0, 20, 40, 0.3) 100%);
  border: 2px solid #444444;
  border-radius: 12px;
  padding: 1.5rem 1.8rem;
  cursor: pointer;
  opacity: 0.7;
  width: 200px;
  height: 110px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 0.6rem;
  position: relative;
  overflow: hidden;
  transition: all 0.3s ease;
  
  .icon {
    font-size: 2.5rem;
    margin: 0;
    color: #888888;
    transition: all 0.3s ease;
    z-index: 2;
    position: relative;
  }
  
  .title {
    color: #888888;
    font-size: 1.1rem;
    font-weight: bold;
    margin: 0;
    text-transform: uppercase;
    letter-spacing: 0.1rem;
    transition: all 0.3s ease;
    z-index: 2;
    position: relative;
  }
  
  /* Diagonaler Sweep-Effekt */
  &::before {
    content: '';
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: linear-gradient(
      45deg,
      transparent 40%, 
      rgba(255, 215, 0, 0.3) 45%, 
      rgba(255, 215, 0, 0.6) 50%, 
      rgba(255, 215, 0, 0.3) 55%, 
      transparent 60%
    );
    transform: translateX(-100%) translateY(-100%);
    transition: transform 0.6s ease;
    z-index: 1;
  }
  
  &:hover {
    border-color: #ffd700;
    transform: scale(1.02);
    
    .icon {
      color: #ffd700;
      filter: drop-shadow(0 0 8px #ffd700);
    }
    
    .title {
      color: #ffd700;
      text-shadow: 0 0 8px #ffd700;
    }
    
    &::before {
      animation: ${diagonalSweep} 0.8s ease;
    }
  }
`;

const SectionTitle = styled.h2`
  color: #ffa500;
  font-size: 1.5rem;
  font-weight: 700;
  margin: 2rem 0 1.5rem 0;
  text-transform: uppercase;
  text-align: center;
  text-shadow: 0 0 5px #ffa500;
`;

// NEON GAMES BUTTON
const NeonGamesButton = styled.button`
  background: transparent;
  border: 2px solid #00ffff;
  color: #ffffff;
  padding: 0.8rem 2rem;
  border-radius: 8px;
  font-size: 1.2rem;
  font-weight: bold;
  font-family: 'Courier New', monospace;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  cursor: pointer;
  transition: all 0.3s ease;
  position: relative;
  
  /* Neon-Effekt wie beim Titel */
  text-shadow: 
    0 0 5px #00ffff,
    0 0 10px #00ffff,
    0 0 15px #00ffff;
  box-shadow: 
    0 0 10px rgba(0, 255, 255, 0.5),
    inset 0 0 10px rgba(0, 255, 255, 0.1);
  
  /* Sanfte Animation */
  animation: ${neonPulse} 6s ease-in-out infinite;
  
  /* Zusätzlicher Glow-Effekt */
  &::before {
    content: '';
    position: absolute;
    top: -2px;
    left: -2px;
    right: -2px;
    bottom: -2px;
    background: linear-gradient(45deg, #00ffff, #ff00ff, #00ffff);
    border-radius: 8px;
    z-index: -1;
    opacity: 0.3;
    animation: ${neonFlicker} 4s linear infinite;
  }

  &:hover {
    transform: scale(1.05);
    border-color: #ff00ff;
    color: #ff00ff;
    text-shadow: 
      0 0 8px #ff00ff,
      0 0 15px #ff00ff,
      0 0 25px #ff00ff;
    box-shadow: 
      0 0 20px rgba(255, 0, 255, 0.8),
      inset 0 0 20px rgba(255, 0, 255, 0.2);
  }

  &:active {
    transform: scale(0.98);
  }
`;

// ==========================================
// COMPONENT
// ==========================================

const SingleplayerZone: React.FC = () => {
  const navigate = useNavigate();

  const singleplayerGames: GameData[] = [
    {
      id: 'snake',
      title: 'Snake',
      icon: '🐍',
      route: '/singleplayer/snake',
      enabled: true,
      description: 'Eat and grow longer',
      difficulty: 'easy'
    },
    {
      id: 'pong',
      title: 'Pong',
      icon: '🏓',
      route: '/singleplayer/pong',
      enabled: true,
      description: 'Classic ping pong vs AI',
      difficulty: 'easy'
    },
    {
      id: 'memory',
      title: 'Memory',
      icon: '🧠',
      route: '/singleplayer/memory',
      enabled: true,
      description: 'Match the pairs',
      difficulty: 'easy'
    },
    {
      id: 'tetris',
      title: 'Tetris',
      icon: '🧩',
      route: '/singleplayer/tetris',
      enabled: true,
      description: 'Classic block puzzle game',
      difficulty: 'medium'
    },
    {
      id: 'breakout',
      title: 'Breakout',
      icon: '🧱',
      route: '/singleplayer/breakout',
      enabled: false,
      requiresProduction: true,
      description: 'Break all the bricks',
      difficulty: 'medium'
    },
    {
      id: 'pacman',
      title: 'Pac-Man',
      icon: '👻',
      route: '/singleplayer/pacman',
      enabled: false,
      requiresProduction: true,
      description: 'Eat dots and avoid ghosts',
      difficulty: 'hard'
    }
  ];

  const handleGameClick = (game: GameData) => {
    if (game.enabled) {
      console.log(`🎮 Starting ${game.title}...`);
      navigate(game.route);
    }
  };

  const availableGames = singleplayerGames.filter(game => 
    !game.requiresProduction
  );
  
  const disabledGames = singleplayerGames.filter(game => 
    game.requiresProduction
  );

  return (
    <ZoneContainer>
      <ZoneHeader>
        {/* GROßER TITEL mit echtem NEON EFFEKT */}
        <BigTitle>
          Singleplayer
        </BigTitle>
        
        <NeonGamesButton onClick={() => navigate('/')}>
          Games
        </NeonGamesButton>
      </ZoneHeader>

      {/* Available Games - Gleiche Größe wie GamesZone Buttons */}
      <GamesGrid>
        {availableGames.map(game => (
          <GameCard
            key={game.id}
            onClick={() => handleGameClick(game)}
          >
            <GameIcon className="icon">{game.icon}</GameIcon>
            <GameTitle className="title">{game.title}</GameTitle>
          </GameCard>
        ))}
      </GamesGrid>

      {/* Premium Games - Gleiche Größe aber disabled Style */}
      {disabledGames.length > 0 && (
        <>
          <SectionTitle>🔒 Premium Games</SectionTitle>
          
          <PremiumGrid>
            {disabledGames.map(game => (
              <PremiumCard key={game.id}>
                <div className="icon">{game.icon}</div>
                <div className="title">{game.title}</div>
              </PremiumCard>
            ))}
          </PremiumGrid>
        </>
      )}
    </ZoneContainer>
  );
};

export default SingleplayerZone;