// Tier Upgrade Path
export interface TierUpgrade {
  from: PaymentTier;
  to: PaymentTier;
  monthlySavings: number;
  yearlySavings: number;
  newFeatures: string[];
}

// ===================================================================
// USER-SPEZIFISCHE PAYMENTMANAGER KLASSE
// ===================================================================

export class PaymentManager {
  private userId: string;
  private baseURL: string;
  private apiPath: string;
  private isDemoMode: boolean;
  private eventListeners: Map<string, Function[]> = new Map();
  private cache: Map<string, { data: any; expiry: number }> = new Map();
  private cacheTimeout: number = 5 * 60 * 1000; // 5 minutes
  private currentTier: PaymentTier = 'free';

  /**
   * WICHTIGER HINWEIS: User-spezifische PaymentManager-Instanzen
   * 
   * Jeder User bekommt seine eigene PaymentManager-Instanz mit:
   * - Separatem Payment-Status und Tier-Level
   * - Isolierten Caches (User A beeinflusst nicht User B)
   * - User-spezifischen API-Calls (userId ist immer verf�gbar)
   * - Unabh�ngigen Event-Listenern pro User
   * 
   * Vorteile gegen�ber Singleton:
   * - Multi-User Support ohne State-Konflikte
   * - Bessere Testbarkeit verschiedener User-Szenarien
   * - Einfachere API-Integration (userId automatisch verf�gbar)
   * - Bessere Performance durch User-spezifische Caches
   */
  constructor(userId: string) {
    if (!userId) {
      throw new Error('PaymentManager requires a valid userId');
    }

    this.userId = userId;
    this.baseURL = process.env.REACT_APP_PAYMENT_URL || 'http://localhost:3002';
    this.apiPath = '/api/payment';
    this.isDemoMode = process.env.REACT_APP_DEMO_MODE === 'true';

    console.log(`[PaymentManager] Created instance for user: ${userId}`);
  }

  // ===================================================================
  // PAYMENT TIER SYSTEM
  // ===================================================================

  async getCurrentTier(): Promise<PaymentTier> {
    const cacheKey = `tier_${this.userId}`;
    const cached = this.getFromCache(cacheKey);
    if (cached) {
      return cached;
    }

    try {
      const billing = await this.getUserBilling();
      if (billing.success && billing.data?.paymentTier) {
        const tier = billing.data.paymentTier;
        this.setCache(cacheKey, tier);
        this.currentTier = tier;
        return tier;
      }
    } catch (error) {
      console.error('[PaymentManager] Failed to get current tier:', error);
    }

    return 'free'; // Fallback
  }

  getTierConfig(tier: PaymentTier): PaymentTierConfig {
    return PAYMENT_TIERS[tier];
  }

  getAllTiers(): PaymentTierConfig[] {
    return Object.values(PAYMENT_TIERS);
  }

  canAccessFeature(tier: PaymentTier, feature: keyof PaymentTierConfig['features']): boolean {
    return Boolean(PAYMENT_TIERS[tier]?.features[feature]);
  }

  async upgradeTier(targetTier: PaymentTier, billingCycle: 'monthly' | 'yearly' = 'monthly'): Promise<ApiResponse<PaymentConfirmation>> {
    try {
      const currentTier = await this.getCurrentTier();
      const tierConfig = this.getTierConfig(targetTier);
      const amount = billingCycle === 'yearly' ? tierConfig.yearlyPrice : tierConfig.monthlyPrice;

      if (currentTier === targetTier) {
        return {
          success: false,
          error: 'Already subscribed to this tier'
        };
      }

      // Process tier upgrade payment - userId ist automatisch verf�gbar
      const paymentResult = await this.processPayment(
        amount, 
        `${targetTier}_${billingCycle}`, 
        targetTier
      );

      if (paymentResult.success) {
        // Update tier cache
        this.currentTier = targetTier;
        this.setCache(`tier_${this.userId}`, targetTier);

        // Emit tier change event
        this.emit('tierUpgraded', {
          userId: this.userId,
          fromTier: currentTier,
          toTier: targetTier,
          billingCycle
        });
      }

      return {
        success: paymentResult.success,
        data: paymentResult,
        error: paymentResult.error
      };

    } catch (error) {
      console.error('[PaymentManager] Failed to upgrade tier:', error);
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Failed to upgrade tier'
      };
    }
  }

  async downgradeTier(targetTier: PaymentTier): Promise<ApiResponse<boolean>> {
    try {
      const response = await fetch(`${this.baseURL}${this.apiPath}/tier/downgrade`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        credentials: 'include',
        body: JSON.stringify({
          userId: this.userId, // Automatisch verf�gbar
          targetTier
        })
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const result = await response.json();

      if (result.success) {
        // Update tier cache
        this.currentTier = targetTier;
        this.setCache(`tier_${this.userId}`, targetTier);

        this.emit('tierDowngraded', {
          userId: this.userId,
          toTier: targetTier
        });
      }

      return result;

    } catch (error) {
      console.error('[PaymentManager] Failed to downgrade tier:', error);
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Failed to downgrade tier'
      };
    }
  }

  getUpgradeRecommendation(currentTier: PaymentTier): TierUpgrade | null {
    const upgrades: Record<PaymentTier, PaymentTier | null> = {
      free: 'basic',
      basic: 'premium', 
      premium: 'ultimate',
      ultimate: null
    };

    const nextTier = upgrades[currentTier];
    if (!nextTier) return null;

    const currentConfig = PAYMENT_TIERS[currentTier];
    const nextConfig = PAYMENT_TIERS[nextTier];

    return {
      from: currentTier,
      to: nextTier,
      monthlySavings: nextConfig.monthlyPrice - currentConfig.monthlyPrice,
      yearlySavings: nextConfig.yearlyPrice - currentConfig.yearlyPrice,
      newFeatures: this.getNewFeatures(currentTier, nextTier)
    };
  }

  private getNewFeatures(fromTier: PaymentTier, toTier: PaymentTier): string[] {
    const currentFeatures = PAYMENT_TIERS[fromTier].features;
    const newFeatures = PAYMENT_TIERS[toTier].features;
    const newFeaturesList: string[] = [];

    Object.entries(newFeatures).forEach(([key, value]) => {
      const currentValue = currentFeatures[key as keyof typeof currentFeatures];
      
      if (typeof value === 'boolean' && value && !currentValue) {
        newFeaturesList.push(key.replace(/([A-Z])/g, ' $1').toLowerCase());
      } else if (typeof value === 'number' && value > (currentValue as number)) {
        newFeaturesList.push(`Increased ${key.replace(/([A-Z])/g, ' $1').toLowerCase()}`);
      }
    });

    return newFeaturesList;
  }

  // ===================================================================
  // PRODUCTS & PLANS
  // ===================================================================

  async loadProducts(): Promise<PaymentProduct[]> {
    const cacheKey = 'payment_products';
    const cached = this.getFromCache(cacheKey);
    if (cached) {
      return cached;
    }

    try {
      const response = await fetch(`${this.baseURL}${this.apiPath}/products`, {
        method: 'GET',
        credentials: 'include',
        headers: {
          'Content-Type': 'application/json'
        }
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const result = await response.json();
      let products = result.products || result.data || [];

      // Erweitere Products mit Tier-Informationen
      products = products.map((product: PaymentProduct) => {
        const tier = this.mapProductToTier(product.id);
        if (tier) {
          const tierConfig = PAYMENT_TIERS[tier];
          return {
            ...product,
            tier,
            tierConfig,
            popular: tierConfig.popular,
            bestValue: tierConfig.bestValue
          };
        }
        return product;
      });

      this.setCache(cacheKey, products);
      return products;

    } catch (error) {
      console.error('[PaymentManager] Failed to load products:', error);
      this.emit('paymentError', `Failed to load products: ${error}`);
      return [];
    }
  }

  private mapProductToTier(productId: string): PaymentTier | null {
    if (productId.includes('basic')) return 'basic';
    if (productId.includes('premium')) return 'premium';
    if (productId.includes('ultimate')) return 'ultimate';
    return null;
  }

  // ===================================================================
  // PAYMENT PROCESSING
  // ===================================================================

  async processPayment(
    amount: number, 
    planType: string, 
    planId: string
  ): Promise<PaymentConfirmation> {
    try {
      console.log(`[PaymentManager] Processing payment: ${amount} ${planType} for user ${this.userId}`);

      if (this.isDemoMode) {
        return await this.processTestPayment(amount, planType, planId);
      }

      const intentResponse = await this.createPaymentIntent(amount, planType, planId);
      
      if (!intentResponse.success || !intentResponse.clientSecret) {
        throw new Error(intentResponse.error || 'Failed to create payment intent');
      }

      const confirmation = await this.confirmPayment(intentResponse.paymentIntentId!, planType);
      
      this.emit('paymentSuccess', confirmation);
      return confirmation;

    } catch (error) {
      console.error('[PaymentManager] Payment processing failed:', error);
      const errorMessage = error instanceof Error ? error.message : 'Payment processing failed';
      this.emit('paymentError', errorMessage);
      
      return {
        success: false,
        error: errorMessage
      };
    }
  }

  async createPaymentIntent(
    amount: number, 
    planType: string, 
    planId: string
  ): Promise<PaymentIntentResponse> {
    try {
      const response = await fetch(`${this.baseURL}/payment/create-intent`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        credentials: 'include',
        body: JSON.stringify({
          amount,
          planType,
          userId: this.userId, // Automatisch verf�gbar
          planId,
          currency: 'eur'
        })
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      return await response.json();

    } catch (error) {
      console.error('[PaymentManager] Failed to create payment intent:', error);
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Failed to create payment intent'
      };
    }
  }

  async confirmPayment(paymentIntentId: string, planType: string): Promise<PaymentConfirmation> {
    try {
      const response = await fetch(`${this.baseURL}/payment/confirm`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        credentials: 'include',
        body: JSON.stringify({
          paymentIntentId,
          planType,
          userId: this.userId // Automatisch verf�gbar
        })
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      return await response.json();

    } catch (error) {
      console.error('[PaymentManager] Failed to confirm payment:', error);
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Failed to confirm payment'
      };
    }
  }

  async processTestPayment(
    amount: number, 
    planType: string, 
    planId: string
  ): Promise<PaymentConfirmation> {
    try {
      return {
        success: true,
        payment: {
          id: `demo_${Date.now()}`,
          amount,
          currency: 'eur',
          status: 'succeeded',
          planType,
          planId,
          paidAt: new Date().toISOString()
        },
        subscription: {
          plan: planType,
          status: 'active',
          paidAt: new Date().toISOString()
        },
        message: 'Demo payment processed successfully',
        demoMode: true
      };

    } catch (error) {
      console.error('[PaymentManager] Test payment failed:', error);
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Test payment failed'
      };
    }
  }

  // ===================================================================
  // BILLING & HISTORY
  // ===================================================================

  async getUserBilling(): Promise<ApiResponse<BillingInfo>> {
    try {
      const response = await fetch(`${this.baseURL}/payment/billing/${this.userId}`, {
        method: 'GET',
        credentials: 'include'
      });
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }
      const result = await response.json();
      
      return {
        success: true,
        data: result
      };
      
    } catch (error) {
      console.error('[PaymentManager] Failed to get billing info:', error);
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Failed to get billing info'
      };
    }
  }

  async getPaymentHistory(
    page: number = 1, 
    limit: number = 10
  ): Promise<ApiResponse<PaymentHistoryEntry[]>> {
    try {
      const response = await fetch(
        `${this.baseURL}/payment/history/${this.userId}?page=${page}&limit=${limit}`, 
        {
          method: 'GET',
          credentials: 'include'
        }
      );
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }
      const result = await response.json();
      
      return {
        success: true,
        data: result
      };
      
    } catch (error) {
      console.error('[PaymentManager] Failed to get payment history:', error);
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Failed to get payment history'
      };
    }
  }

  // ===================================================================
  // EVENT SYSTEM
  // ===================================================================

  on(event: string, callback: Function): void {
    if (!this.eventListeners.has(event)) {
      this.eventListeners.set(event, []);
    }
    this.eventListeners.get(event)!.push(callback);
  }

  off(event: string, callback: Function): void {
    if (this.eventListeners.has(event)) {
      const listeners = this.eventListeners.get(event)!;
      const index = listeners.indexOf(callback);
      if (index > -1) {
        listeners.splice(index, 1);
      }
    }
  }

  private emit(event: string, data: any): void {
    if (this.eventListeners.has(event)) {
      this.eventListeners.get(event)!.forEach(callback => {
        try {
          callback(data);
        } catch (error) {
          console.error(`[PaymentManager] Error in event listener for ${event}:`, error);
        }
      });
    }
  }

  // ===================================================================
  // CACHE MANAGEMENT
  // ===================================================================

  private setCache(key: string, data: any, timeout?: number): void {
    const expiry = Date.now() + (timeout || this.cacheTimeout);
    this.cache.set(key, { data, expiry });
  }

  private getFromCache(key: string): any | null {
    const cached = this.cache.get(key);
    if (!cached) return null;
    
    if (Date.now() > cached.expiry) {
      this.cache.delete(key);
      return null;
    }
    
    return cached.data;
  }

  clearCache(): void {
    this.cache.clear();
  }

  // ===================================================================
  // UTILITY METHODS
  // ===================================================================

  async healthCheck(): Promise<boolean> {
    try {
      const response = await fetch(`${this.baseURL}/health`, {
        method: 'GET',
        credentials: 'include'
      });
      
      return response.ok;
    } catch (error) {
      console.error('[PaymentManager] Health check failed:', error);
      return false;
    }
  }

  getConfig(): PaymentManagerConfig {
    return {
      baseURL: this.baseURL,
      apiPath: this.apiPath,
      isDemoMode: this.isDemoMode,
      cacheTimeout: this.cacheTimeout,
      userId: this.userId
    };
  }

  isDemoModeEnabled(): boolean {
    return this.isDemoMode;
  }

  getUserId(): string {
    return this.userId;
  }
}

// Export der Klasse (nicht als Singleton-Instanz)
export default PaymentManager;