import React, { useState } from 'react';

// Types
interface PaymentPlan {
  id: string;
  name: string;
  description: string;
  price: number;
  currency: string;
  interval_type: string;
  isActive: boolean;
  popular?: boolean;
  bestValue?: boolean;
  originalPrice?: number;
  savings?: number;
  features: string[];
}

interface User {
  id: number | string;
  username?: string;
  name?: string;
  email: string;
  displayName?: string;
  membershipTier?: string;
  subscriptionStatus?: string;
}

interface PricingPageProps {
  user?: User;
  onSubscriptionSuccess?: (plan: PaymentPlan) => void;
}

// Simple navigation function - no hooks
const createNavigateFunction = () => {
  return (path: string) => {
    if (path === '/profile' || path.includes('profile')) {
      window.history.back(); // Go back to previous page
    } else {
      console.log('Navigating to:', path);
      // You could also use window.location.href = path if needed
    }
  };
};

