// Enhanced Payment Form Component (moved outside main component)
const EnhancedPaymentForm: React.FC<{
  plan: PaymentPlan;
  user: User;
  onSuccess?: (result: any) => void;
  onCancel?: () => void;
}> = ({ plan, user, onSuccess, onCancel }) => {
  const [selectedMethod, setSelectedMethod] = useState<'card' | 'paypal' | 'crypto'>('card');
  const [loading, setLoading] = useState(false);
  const [cardNumber, setCardNumber] = useState('');
  const [expiry, setExpiry] = useState('');
  const [cvc, setCvc] = useState('');
  const [cardComplete, setCardComplete] = useState(false);

  const paymentMethods = [
    { id: 'card', name: 'Credit Card', icon: '💳' },
    { id: 'paypal', name: 'PayPal', icon: '🛒' },
    { id: 'crypto', name: 'Crypto', icon: '₿' }
  ];

  const handleCardNumberChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let value = e.target.value.replace(/\s/g, '');
    value = value.replace(/(.{4})/g, '$1 ').trim();
    if (value.length <= 19) {
      setCardNumber(value);
      checkFormComplete(value, expiry, cvc);
    }
  };

  const handleExpiryChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let value = e.target.value.replace(/\D/g, '');
    if (value.length >= 2) {
      value = value.substring(0,2) + '/' + value.substring(2,4);
    }
    if (value.length <= 5) {
      setExpiry(value);
      checkFormComplete(cardNumber, value, cvc);
    }
  };

  const handleCvcChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value.replace(/\D/g, '');
    if (value.length <= 3) {
      setCvc(value);
      checkFormComplete(cardNumber, expiry, value);
    }
  };

  const checkFormComplete = (card: string, exp: string, cvcVal: string) => {
    const complete = card.replace(/\s/g, '').length >= 16 && exp.length === 5 && cvcVal.length >= 3;
    setCardComplete(complete);
  };

  const handleSubmit = async () => {
    setLoading(true);
    
    // Simulate payment processing
    await new Promise(resolve => setTimeout(resolve, 2000));
    
    setLoading(false);
    onSuccess?.({ 
      success: true, 
      method: selectedMethod, 
      plan: plan.name,
      amount: plan.price 
    });
  };

  const renderPaymentForm = () => {
    switch (selectedMethod) {
      case 'card':
        return (
          <div style={{ marginBottom: '1.5rem' }}>
            <div style={{
              border: `2px solid ${cardComplete ? '#00ff88' : '#444'}`,
              borderRadius: '8px',
              padding: '1rem',
              background: cardComplete ? 'rgba(0, 255, 136, 0.1)' : 'rgba(0, 0, 0, 0.3)',
              transition: 'all 0.3s ease'
            }}>
              <input
                type="text"
                placeholder="Card number"
                value={cardNumber}
                onChange={handleCardNumberChange}
                style={{
                  width: '100%',
                  background: 'transparent',
                  border: 'none',
                  fontSize: '1.1rem',
                  color: 'white',
                  marginBottom: '0.5rem',
                  outline: 'none'
                }}
              />
              <div style={{ display: 'flex', gap: '1rem' }}>
                <input
                  type="text"
                  placeholder="MM/YY"
                  value={expiry}
                  onChange={handleExpiryChange}
                  style={{
                    flex: 1,
                    background: 'transparent',
                    border: 'none',
                    color: 'white',
                    outline: 'none'
                  }}
                />
                <input
                  type="text"
                  placeholder="CVC"
                  value={cvc}
                  onChange={handleCvcChange}
                  style={{
                    flex: 1,
                    background: 'transparent',
                    border: 'none',
                    color: 'white',
                    outline: 'none'
                  }}
                />
              </div>
            </div>
            <div style={{
              background: 'rgba(0, 255, 136, 0.1)',
              border: '1px solid rgba(0, 255, 136, 0.3)',
              borderRadius: '8px',
              padding: '1rem',
              marginTop: '1rem',
              fontSize: '0.9rem'
            }}>
              <h4 style={{ color: '#00ff88', margin: '0 0 0.5rem 0' }}>💳 Demo Test Cards:</h4>
              <div style={{ color: 'rgba(255, 255, 255, 0.8)' }}>
                <div><strong>Success:</strong> 4242 4242 4242 4242</div>
                <div><strong>Decline:</strong> 4000 0000 0000 0002</div>
                <div><strong>Any expiry date and CVC</strong></div>
              </div>
            </div>
          </div>
        );

      case 'paypal':
        return (
          <div style={{
            border: '2px solid #ffc439',
            borderRadius: '8px',
            padding: '2rem',
            background: 'rgba(255, 196, 57, 0.1)',
            textAlign: 'center',
            margin: '1.5rem 0'
          }}>
            <div style={{ fontSize: '2rem', color: '#0070ba', marginBottom: '1rem' }}>PayPal</div>
            <p style={{ color: '#ddd', marginBottom: '0.5rem' }}>
              You will be redirected to PayPal to complete your payment securely.
            </p>
            <p style={{ fontSize: '0.8rem', color: '#aaa' }}>
              🎭 Demo: PayPal integration simulation
            </p>
          </div>
        );

      case 'crypto':
        return (
          <div style={{
            border: '2px solid #f7931a',
            borderRadius: '8px',
            padding: '2rem',
            background: 'rgba(247, 147, 26, 0.1)',
            textAlign: 'center',
            margin: '1.5rem 0'
          }}>
            <div style={{ fontSize: '2rem', color: '#f7931a', marginBottom: '1rem' }}>₿</div>
            <p style={{ fontWeight: 'bold', marginBottom: '1rem', color: 'white' }}>
              Bitcoin Payment Address:
            </p>
            <div style={{
              background: 'rgba(0, 0, 0, 0.5)',
              padding: '0.5rem',
              borderRadius: '4px',
              fontFamily: 'monospace',
              fontSize: '0.8rem',
              margin: '0.5rem 0',
              wordBreak: 'break-all',
              color: '#f7931a'
            }}>
              bc1qxy2kgdygjrsqtzq2n0yrf2493p83kkfjhx0wlh
            </div>
            <p style={{ fontSize: '0.9rem', color: '#ddd' }}>
              Amount: <strong>{plan.price} EUR</strong> ≈ 0.0023 BTC
            </p>
            <p style={{ fontSize: '0.8rem', color: '#aaa', marginTop: '0.5rem' }}>
              🎭 Demo: Crypto payment simulation
            </p>
          </div>
        );

      default:
        return null;
    }
  };

  const isFormValid = () => {
    switch (selectedMethod) {
      case 'card':
        return cardComplete;
      case 'paypal':
      case 'crypto':
        return true;
      default:
        return false;
    }
  };

  return (
    <div style={{
      background: 'rgba(0, 0, 0, 0.95)',
      padding: '2rem',
      borderRadius: '15px',
      border: '3px solid #00ffff',
      maxWidth: '600px',
      maxHeight: '90vh',
      overflowY: 'auto',
      margin: '0 auto',
      backdropFilter: 'blur(10px)',
      boxShadow: '0 0 30px rgba(0, 255, 255, 0.5)',
      fontFamily: 'Courier New, monospace',
      color: 'white'
    }}>
      {/* Demo Banner */}
      <div style={{
        background: 'linear-gradient(90deg, #00ff88, #00ccff)',
        color: '#1a1a2e',
        padding: '1rem',
        borderRadius: '8px',
        marginBottom: '2rem',
        textAlign: 'center',
        fontWeight: 'bold'
      }}>
        <h3 style={{ margin: '0 0 0.5rem 0', fontSize: '1.2rem' }}>🎭 Demo Mode Active</h3>
        <p style={{ margin: '0', fontSize: '0.9rem', opacity: 0.9 }}>
          This is a fully functional demo - no real payments will be processed!
        </p>
      </div>

      {/* Plan Header */}
      <div style={{ textAlign: 'center', marginBottom: '2rem' }}>
        <h2 style={{ color: '#00ff88', marginBottom: '0.5rem', fontSize: '1.8rem' }}>
          Subscribe to {plan.name}
        </h2>
        <div style={{ fontSize: '2.5rem', fontWeight: 'bold', color: '#00ccff', marginBottom: '0.5rem' }}>
          €{plan.price.toFixed(2)}
          {plan.originalPrice && (
            <span style={{ 
              fontSize: '1rem', 
              textDecoration: 'line-through', 
              color: '#666', 
              marginLeft: '0.5rem' 
            }}>
              €{plan.originalPrice.toFixed(2)}
            </span>
          )}
        </div>
        <div style={{ color: '#aaa', fontSize: '1rem' }}>{plan.description}</div>
        {plan.savings && (
          <div style={{ color: '#00ff88', fontWeight: 'bold', marginTop: '0.5rem' }}>
            Save €{plan.savings.toFixed(2)}!
          </div>
        )}
      </div>

      {/* Payment Method Selector */}
      <div style={{ marginBottom: '2rem' }}>
        <h3 style={{ color: '#00ff88', marginBottom: '1rem', fontSize: '1.1rem' }}>
          Choose Payment Method
        </h3>
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(3, 1fr)',
          gap: '1rem',
          marginBottom: '1.5rem'
        }}>
          {paymentMethods.map((method) => (
            <div
              key={method.id}
              style={{
                border: `2px solid ${selectedMethod === method.id ? '#00ccff' : '#444'}`,
                borderRadius: '8px',
                padding: '1rem',
                textAlign: 'center',
                cursor: 'pointer',
                transition: 'all 0.2s',
                background: selectedMethod === method.id ? 'rgba(0, 204, 255, 0.1)' : 'rgba(0, 0, 0, 0.3)'
              }}
              onClick={() => setSelectedMethod(method.id as any)}
              onMouseOver={(e) => {
                if (selectedMethod !== method.id) {
                  e.currentTarget.style.borderColor = '#00ccff';
                }
              }}
              onMouseOut={(e) => {
                if (selectedMethod !== method.id) {
                  e.currentTarget.style.borderColor = '#444';
                }
              }}
            >
              <div style={{ fontSize: '1.5rem', marginBottom: '0.5rem' }}>{method.icon}</div>
              <div style={{ fontSize: '0.9rem', fontWeight: 600 }}>{method.name}</div>
            </div>
          ))}
        </div>
      </div>

      {/* Payment Form */}
      {renderPaymentForm()}

      {/* Action Buttons */}
      <button 
        onClick={handleSubmit}
        disabled={loading || !isFormValid()}
        style={{
          width: '100%',
          padding: '1rem',
          background: loading || !isFormValid() ? '#666' : 'linear-gradient(90deg, #00ff88, #00cc66)',
          color: loading || !isFormValid() ? '#aaa' : '#000',
          border: 'none',
          borderRadius: '8px',
          fontSize: '1.1rem',
          fontWeight: 'bold',
          cursor: loading || !isFormValid() ? 'not-allowed' : 'pointer',
          transition: 'all 0.3s ease',
          marginBottom: '1rem'
        }}
      >
        {loading ? 'Processing...' : `Pay €${plan.price.toFixed(2)} via ${selectedMethod.toUpperCase()}`}
      </button>
      
      <button 
        onClick={onCancel}
        style={{
          width: '100%',
          padding: '0.75rem',
          background: 'transparent',
          border: '2px solid #666',
          color: '#ddd',
          borderRadius: '8px',
          cursor: 'pointer',
          transition: 'all 0.3s ease'
        }}
        onMouseOver={(e) => {
          e.currentTarget.style.borderColor = '#00ccff';
          e.currentTarget.style.color = '#00ccff';
        }}
        onMouseOut={(e) => {
          e.currentTarget.style.borderColor = '#666';
          e.currentTarget.style.color = '#ddd';
        }}
      >
        Cancel
      </button>
    </div>
  );
};

// Main PricingPage Component
const PricingPage: React.FC<PricingPageProps> = ({ 
  user: propsUser, 
  onSubscriptionSuccess 
}) => {
  const navigate = createNavigateFunction();
  const [plans] = useState<PaymentPlan[]>(SUBSCRIPTION_PLANS);
  const [selectedPlan, setSelectedPlan] = useState<PaymentPlan | null>(null);
  const [demoMode] = useState(true);
  
  // Use provided user or fallback to mock user
  const user: User = propsUser || {
    id: '1',
    name: 'Retro Gamer',
    email: 'gamer@retro.com'
  };

  const handlePlanSelect = (plan: PaymentPlan) => {
    if (plan.price === 0) {
      console.log('🆓 Free plan selected');
      
      if (onSubscriptionSuccess) {
        onSubscriptionSuccess(plan);
      } else {
        alert('🎮 Welcome to Retro Gaming! Free plan activated!');
      }
      return;
    }
    
    setSelectedPlan(plan);
  };

  const handlePaymentSuccess = (result: any) => {
    console.log('🎉 Payment successful!', result);
    setSelectedPlan(null);
    
    if (onSubscriptionSuccess && selectedPlan) {
      onSubscriptionSuccess(selectedPlan);
    } else {
      alert('🎮 Welcome to Retro Gaming! Your subscription is now active!');
    }
  };

  const handlePaymentCancel = () => {
    setSelectedPlan(null);
  };

  const handleBackClick = () => {
    console.log('👤 Navigating back to profile');
    navigate('/profile');
  };

  const getPlanColors = (planId: string) => {
    switch(planId) {
      case 'starter':
        return {
          border: '#00ff88',
          glow: 'rgba(0, 255, 136, 0.5)',
          button: 'linear-gradient(90deg, #00ff88, #00cc66)',
          text: '#00ff88'
        };
      case 'gamer':
        return {
          border: '#00ccff',
          glow: 'rgba(0, 204, 255, 0.5)',
          button: 'linear-gradient(90deg, #00ccff, #0099cc)',
          text: '#00ccff'
        };
      case 'pro':
        return {
          border: '#ffd700',
          glow: 'rgba(255, 215, 0, 0.5)',
          button: 'linear-gradient(90deg, #ffd700, #ffaa00)',
          text: '#ffd700'
        };
      default:
        return {
          border: '#00ff88',
          glow: 'rgba(0, 255, 136, 0.5)',
          button: 'linear-gradient(90deg, #00ff88, #00cc66)',
          text: '#00ff88'
        };
    }
  };

  return (
    <div style={{
      fontFamily: 'Courier New, monospace',
      background: 'linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%)',
      color: '#ffffff',
      minHeight: '100vh',
      padding: '2rem'
    }}>
      {/* CSS Animations */}
      <style>{`
        @keyframes neonPulse {
          0% { text-shadow: 0 0 15px currentColor, 0 0 30px currentColor, 0 0 45px currentColor; }
          100% { text-shadow: 0 0 8px currentColor, 0 0 15px currentColor, 0 0 25px currentColor; }
        }
        @keyframes coinSpin {
          0% { transform: rotateY(0deg); }
          100% { transform: rotateY(360deg); }
        }
        @keyframes boxGlow {
          0% { box-shadow: 0 0 20px var(--glow-color), 0 0 40px var(--glow-color); }
          100% { box-shadow: 0 0 30px var(--glow-color), 0 0 60px var(--glow-color); }
        }
        .neon-text { animation: neonPulse 2s infinite alternate; }
        .coin-spin { animation: coinSpin 3s linear infinite; }
        .glow-box { animation: boxGlow 3s infinite alternate; }
      `}</style>

      <div style={{ maxWidth: '1400px', margin: '0 auto' }}>
        {/* Header */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '3rem' }}>
          <button 
            onClick={handleBackClick}
            style={{
              background: 'transparent',
              border: '2px solid #00ffff',
              color: '#00ffff',
              padding: '0.7rem 1.5rem',
              borderRadius: '8px',
              fontSize: '1rem',
              fontWeight: 'bold',
              cursor: 'pointer',
              textTransform: 'uppercase',
              textShadow: '0 0 5px #00ffff',
              transition: 'all 0.3s ease'
            }}
            onMouseOver={(e) => {
              e.currentTarget.style.background = 'rgba(0, 255, 255, 0.1)';
              e.currentTarget.style.transform = 'scale(1.05)';
              e.currentTarget.style.boxShadow = '0 0 15px rgba(0, 255, 255, 0.6)';
            }}
            onMouseOut={(e) => {
              e.currentTarget.style.background = 'transparent';
              e.currentTarget.style.transform = 'scale(1)';
              e.currentTarget.style.boxShadow = 'none';
            }}
          >
            ← PROFILE
          </button>
          
          <div style={{ textAlign: 'center' }}>
            <h1 
              className="neon-text"
              style={{
                fontSize: '4rem',
                fontWeight: 'bold',
                color: '#00ff88',
                margin: '0',
                letterSpacing: '0.3rem',
                textTransform: 'uppercase'
              }}
            >
              PAYMENT
            </h1>
            <p style={{
              color: '#a0a0a0',
              fontSize: '1.2rem',
              maxWidth: '600px',
              margin: '1rem auto 0'
            }}>
              Choose your subscription plan and unlock the ultimate retro gaming experience
            </p>
          </div>
          
          <div style={{ width: '120px' }}></div>
        </div>

        {/* Demo Banner */}
        {demoMode && (
          <div style={{
            background: 'linear-gradient(90deg, #00ff88, #00ccff)',
            color: '#1a1a2e',
            padding: '1rem 2rem',
            borderRadius: '10px',
            marginBottom: '2rem',
            textAlign: 'center',
            fontWeight: 'bold',
            boxShadow: '0 0 20px rgba(0, 255, 136, 0.3)'
          }}>
            <h3 style={{ margin: '0 0 0.5rem 0', fontSize: '1.2rem' }}>🎭 DEVELOPMENT MODE</h3>
            <p style={{ margin: '0', opacity: 0.8 }}>Payment system in development mode - demo transactions only</p>
          </div>
        )}

        {/* Plans Grid */}
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(350px, 1fr))',
          gap: '2rem',
          marginTop: '3rem'
        }}>
          {plans.map((plan) => {
            const colors = getPlanColors(plan.id);
            return (
              <div
                key={plan.id}
                className="glow-box"
                style={{
                  '--glow-color': colors.glow,
                  background: 'rgba(0, 0, 0, 0.9)',
                  border: `4px solid ${colors.border}`,
                  borderRadius: '15px',
                  padding: '2rem',
                  cursor: 'pointer',
                  transition: 'all 0.3s ease',
                  position: 'relative',
                  backdropFilter: 'blur(10px)',
                  transform: plan.popular ? 'scale(1.05)' : 'scale(1)'
                } as React.CSSProperties}
                onClick={() => handlePlanSelect(plan)}
                onMouseOver={(e) => {
                  e.currentTarget.style.transform = plan.popular ? 'scale(1.1)' : 'scale(1.05)';
                }}
                onMouseOut={(e) => {
                  e.currentTarget.style.transform = plan.popular ? 'scale(1.05)' : 'scale(1)';
                }}
              >
                {/* Featured Badge */}
                {(plan.popular || plan.bestValue) && (
                  <div style={{
                    position: 'absolute',
                    top: '-15px',
                    left: '50%',
                    transform: 'translateX(-50%)',
                    background: 'linear-gradient(90deg, #ffaa00, #ff6600)',
                    color: 'white',
                    padding: '0.5rem 1.5rem',
                    borderRadius: '25px',
                    fontSize: '0.8rem',
                    fontWeight: 'bold',
                    textTransform: 'uppercase',
                    boxShadow: '0 0 15px rgba(255, 170, 0, 0.5)'
                  }}>
                    {plan.bestValue ? 'Best Value' : 'Most Popular'}
                  </div>
                )}
                
                {/* Plan Header */}
                <div style={{ textAlign: 'center', marginBottom: '2rem' }}>
                  <h3 
                    className="neon-text"
                    style={{
                      fontSize: '2rem',
                      color: colors.text,
                      marginBottom: '1rem',
                      textTransform: 'uppercase',
                      letterSpacing: '2px',
                      fontWeight: 'bold'
                    }}
                  >
                    {plan.name}
                  </h3>
                  
                  <div style={{ marginBottom: '1rem' }}>
                    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '1rem', marginBottom: '0.5rem' }}>
                      <span 
                        className="coin-spin"
                        style={{
                          fontSize: '3rem',
                          filter: `drop-shadow(0 0 10px ${colors.border})`
                        }}
                      >
                        🪙
                      </span>
                      <span style={{
                        fontSize: '3.5rem',
                        fontWeight: 'bold',
                        background: `linear-gradient(90deg, ${colors.text}, ${colors.border})`,
                        backgroundClip: 'text',
                        WebkitBackgroundClip: 'text',
                        WebkitTextFillColor: 'transparent'
                      }}>
                        €{plan.price.toFixed(2)}
                      </span>
                      <span style={{ fontSize: '1.2rem', color: '#888' }}>/{plan.interval_type}</span>
                    </div>
                    
                    {plan.originalPrice && (
                      <div style={{ fontSize: '1.2rem', textDecoration: 'line-through', color: '#666' }}>
                        €{plan.originalPrice.toFixed(2)}
                      </div>
                    )}
                  </div>
                  
                  <div style={{ color: '#a0a0a0', fontSize: '1rem', marginBottom: '1rem' }}>
                    {plan.description}
                  </div>
                  
                  {plan.savings && (
                    <div style={{
                      color: '#00ff88',
                      fontWeight: 'bold',
                      fontSize: '1.1rem',
                      textShadow: '0 0 10px rgba(0, 255, 136, 0.5)'
                    }}>
                      Save €{plan.savings.toFixed(2)}!
                    </div>
                  )}
                </div>
                
                {/* Features */}
                <ul style={{ listStyle: 'none', padding: 0, margin: '2rem 0' }}>
                  {plan.features.map((feature, index) => (
                    <li 
                      key={index}
                      style={{
                        padding: '0.75rem 0',
                        color: '#ddd',
                        display: 'flex',
                        alignItems: 'center',
                        borderBottom: '1px solid rgba(255, 255, 255, 0.1)',
                        fontSize: '0.95rem'
                      }}
                    >
                      <span style={{
                        color: colors.text,
                        fontWeight: 'bold',
                        marginRight: '1rem',
                        fontSize: '1.2rem',
                        textShadow: `0 0 10px ${colors.glow}`
                      }}>
                        ✓
                      </span>
                      {feature}
                    </li>
                  ))}
                </ul>
                
                {/* Select Button */}
                <button 
                  style={{
                    width: '100%',
                    padding: '1.2rem',
                    background: colors.button,
                    color: plan.id === 'pro' ? '#1a1a2e' : 'white',
                    border: 'none',
                    borderRadius: '10px',
                    fontSize: '1.1rem',
                    fontWeight: 'bold',
                    cursor: 'pointer',
                    textTransform: 'uppercase',
                    letterSpacing: '1px',
                    transition: 'all 0.3s ease'
                  }}
                  onClick={(e) => {
                    e.stopPropagation();
                    handlePlanSelect(plan);
                  }}
                  onMouseOver={(e) => {
                    e.currentTarget.style.transform = 'translateY(-2px)';
                    e.currentTarget.style.boxShadow = `0 10px 25px ${colors.glow}`;
                  }}
                  onMouseOut={(e) => {
                    e.currentTarget.style.transform = 'translateY(0)';
                    e.currentTarget.style.boxShadow = 'none';
                  }}
                >
                  {plan.price === 0 ? 'Get Started Free' : `Choose ${plan.name}`}
                </button>
              </div>
            );
          })}
        </div>

        {/* Payment Modal */}
        {selectedPlan && (
          <div style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: 'rgba(0, 0, 0, 0.8)',
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center',
            zIndex: 1000,
            padding: '1rem'
          }}>
            <EnhancedPaymentForm
              plan={selectedPlan}
              user={user}
              onSuccess={handlePaymentSuccess}
              onCancel={handlePaymentCancel}
            />
          </div>
        )}
      </div>
    </div>
  );
};

export default PricingPage;