export const RETRO_MODES = {
  // Demo Zugang (ohne Registrierung)
  DEMO: 'demo',
  
  // Production Level (mit Registrierung)  
  LEVEL01: 'level01',
  LEVEL02: 'level02', 
  VIP: 'vip',
  
  // Premium (mit Payment)
  PREMIUM: 'premium',
  
  // Admin (Vollzugriff)
  ADMIN: 'admin'
} as const;

export type RetroRetroMode = typeof RETRO_MODES[keyof typeof RETRO_MODES];

// Game-Kategorien für granulare Steuerung
export interface GameAccess {
  singlePlayer: {
    basic: boolean;      // Snake, Pong, Memory
    extended: boolean;   // Alle Singleplayer
    premium: boolean;    // Premium Singleplayer
  };
  multiPlayer: {
    selected: boolean;   // Ausgewählte Multiplayer
    all: boolean;        // Alle Multiplayer
  };
  arcade: {
    enabled: boolean;    // Arcade-Spiele
  };
}

// Konfigurierbare Mode-Konfiguration
