// Mode Context für Provider-Pattern
interface ModeContextType {
  mode: RetroRetroMode;
  config: ModeConfig;
  setMode: (mode: RetroRetroMode) => void;
  canSwitchMode: boolean;
  gameAccess: GameAccess;
  membershipLevel: string;
}

const ModeContext = createContext<ModeContextType | undefined>(undefined);

// Konfigurierbare Mode Provider Component
export const ModeProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [mode, setModeState] = useState<RetroRetroMode>(RETRO_MODES.DEMO);
  const [loading, setLoading] = useState(true);
  
  const { authorityLevel, isAuthenticated } = useAuth();

  // Authority-zu-Mode Mapping (zentral konfigurierbar)
  useEffect(() => {
    let detectedMode: RetroRetroMode = RETRO_MODES.DEMO; // Sichere Fallback
  
    switch (authorityLevel) {
      case 'ADMIN':
        detectedMode = RETRO_MODES.ADMIN;
        break;
      case 'PRODUCTION':
        detectedMode = RETRO_MODES.PREMIUM;
        break;
      default:
        detectedMode = RETRO_MODES.DEMO;
        break;
    }
   
    console.log(`👤 Authority: ${authorityLevel} → Mode: ${detectedMode.toUpperCase()}`);
    console.log(`🔐 Registered: ${isAuthenticated ? 'YES' : 'NO'}`);
    
    setModeState(detectedMode);
    setLoading(false);
  }, [authorityLevel, isAuthenticated]);
  
  const config = MODE_CONFIGS[mode];
  const canSwitchMode = config.allowModeSwitch;
  
  const setMode = (newMode: RetroRetroMode) => {
    if (canSwitchMode) {
      console.log(`🔄 Mode Switch: ${mode.toUpperCase()} → ${newMode.toUpperCase()}`);
      setModeState(newMode);
    } else {
      console.warn(`🚫 Mode switching disabled for ${config.membershipLevel}`);
    }
  };
  
  // Mode-Änderungen loggen
  useEffect(() => {
    if (!loading) {
      console.log(`🎮 RetroRetro Mode: ${mode.toUpperCase()}`);
      console.log(`💎 Membership: ${config.membershipLevel}`);
      console.log(`🎯 Game Access:`, config.gameAccess);
    }
  }, [mode, config, loading]);
  
  const contextValue: ModeContextType = {
    mode,
    config,
    setMode,
    canSwitchMode,
    gameAccess: config.gameAccess,
    membershipLevel: config.membershipLevel
  };
  
  return (
    <ModeContext.Provider value={contextValue}>
      {children}
    </ModeContext.Provider>
  );
};

// Main Hook
export const useModeDetection = () => {
  const context = useContext(ModeContext);
  
  if (context === undefined) {
    throw new Error('useModeDetection must be used within a ModeProvider');
  }
  
  return context;
};

// Spezifische Feature-Hooks (konfigurierbar)
export const useGameAccess = () => {
  const { gameAccess, membershipLevel } = useModeDetection();
  
  return {
    // Singleplayer Zugriff
    canPlayBasicGames: gameAccess.singlePlayer.basic,           // Snake, Pong, Memory
    canPlayAllSingleplayer: gameAccess.singlePlayer.extended,   // Alle Singleplayer
    canPlayPremiumGames: gameAccess.singlePlayer.premium,       // Premium Games
    
    // Multiplayer Zugriff  
    canPlaySelectedMultiplayer: gameAccess.multiPlayer.selected, // Ausgewählte MP
    canPlayAllMultiplayer: gameAccess.multiPlayer.all,          // Alle MP
    
    // Arcade Zugriff
    canPlayArcade: gameAccess.arcade.enabled,                   // Arcade Games
    
    // Membership Info
    membershipLevel,
    
    // Helper Functions
    hasBasicAccess: () => gameAccess.singlePlayer.basic,
    hasFullAccess: () => gameAccess.singlePlayer.premium && gameAccess.arcade.enabled
  };
};

export const useAdminFeatures = () => {
  const { config, mode } = useModeDetection();
  
  return {
    isAdmin: mode === RETRO_MODES.ADMIN,
    showDebugInfo: config.showDebugInfo,
    showUserManagement: config.showUserManagement,
    showAnalytics: config.showAnalytics,
    canSwitchModes: config.allowModeSwitch,
    canManageUsers: config.showUserManagement
  };
};

export const useUpgradePrompts = () => {
  const { config, mode } = useModeDetection();
  
  return {
    shouldShowUpgrade: config.showUpgradePrompts,
    showDemoNotices: config.showDemoNotices,
    currentLevel: config.membershipLevel,
    
    // Upgrade-Pfade
    getUpgradePath: () => {
      switch (mode) {
        case RETRO_MODES.DEMO:
          return { next: 'LEVEL01', message: 'Registriere dich für mehr Games!' };
        case RETRO_MODES.LEVEL01:
          return { next: 'LEVEL02', message: 'Upgrade für Multiplayer-Zugang!' };
        case RETRO_MODES.LEVEL02:
          return { next: 'VIP', message: 'Werde VIP für alle Features!' };
        case RETRO_MODES.VIP:
          return { next: 'PREMIUM', message: 'Premium für Arcade-Games!' };
        default:
          return null;
      }
    }
  };
};

// Session & Limit Management
export const useSessionLimits = () => {
  const { config } = useModeDetection();
  
  return {
    requiresRegistration: config.requiresRegistration,
    sessionLimitMonths: config.sessionLimitMonths || 0,
    sessionLimitHours: config.sessionLimitHours || 0,
    hasSessionLimit: Boolean(config.sessionLimitMonths || config.sessionLimitHours),
    paymentRequired: config.paymentRequired
  };
};

// Konfiguration für externe Nutzung exportieren
export { MODE_CONFIGS };

export default useModeDetection;
 
export const useGameZoneFeatures = () => {
  const { gameAccess, config, mode } = useModeDetection();
  
  return {
    enabled: true,
    allZones: gameAccess.singlePlayer.extended || gameAccess.multiPlayer.all || gameAccess.arcade.enabled,
    debug: config.showDebugInfo,
    limitedMultiplayer: !gameAccess.multiPlayer.all,
    premium: gameAccess.arcade.enabled,
    singleplayerEnabled: gameAccess.singlePlayer.basic,
    multiplayerEnabled: gameAccess.multiPlayer.selected,
    arcadeEnabled: gameAccess.arcade.enabled,
    currentMode: mode,
    isDemo: mode === RETRO_MODES.DEMO,
    isPremium: mode === RETRO_MODES.PREMIUM,
    hasFullAccess: gameAccess.arcade.enabled && gameAccess.multiPlayer.all
  };
};

export const canAccessArcade = (mode: RetroRetroMode): boolean => {
  return mode === RETRO_MODES.PREMIUM || mode === RETRO_MODES.ADMIN;
};