import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../../managers/AuthManager/hooks/useAuth';
import { socketManager } from '../../../managers/SocketManager';
import GameLobby from './GameLobby';
import GameRoom from './GameRoom';
import styled from 'styled-components';

// Styled Components
const Container = styled.div`
  font-family: 'Courier New', monospace;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
  color: #ffffff;
  min-height: 100vh;
`;

const BackButton = styled.button`
  position: absolute;
  top: 20px;
  left: 20px;
  background: rgba(255, 71, 87, 0.2);
  border: 2px solid #ff4757;
  color: #ff4757;
  padding: 10px 20px;
  border-radius: 8px;
  cursor: pointer;
  font-weight: bold;
  transition: all 0.3s ease;
  
  &:hover {
    background: rgba(255, 71, 87, 0.3);
    transform: scale(1.05);
  }
`;

const ErrorMessage = styled.div`
  color: #fff;
  text-align: center;
  margin-top: 4rem;
  
  h2 {
    color: #ff4757;
    margin-bottom: 1rem;
  }
  
  button {
    background: #ff4757;
    border: none;
    color: #fff;
    padding: 12px 24px;
    border-radius: 8px;
    cursor: pointer;
    font-weight: bold;
    margin-top: 1rem;
    
    &:hover {
      background: #ff6b7a;
    }
  }
`;

type ViewType = 'lobby' | 'room';

const MultiplayerZone: React.FC = () => {
  const navigate = useNavigate();
  const { isLoggedIn, currentUser } = useAuth();
  const [currentView, setCurrentView] = useState<ViewType>('lobby');
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [currentGameType, setCurrentGameType] = useState<string>('');

  // Socket vom SocketManager holen
  const socket = socketManager.getSocket();

  // Nicht eingeloggt
  if (!isLoggedIn || !currentUser) {
    return (
      <Container>
        <ErrorMessage>
          <h2>Authentication Required</h2>
          <p>Please log in to access multiplayer games</p>
          <button onClick={() => navigate('/login')}>Go to Login</button>
        </ErrorMessage>
      </Container>
    );
  }

  // Socket nicht verbunden
  if (!socket) {
    return (
      <Container>
        <ErrorMessage>
          <h2>Connecting to server...</h2>
          <p>Please wait while we establish connection</p>
        </ErrorMessage>
      </Container>
    );
  }

  const gameUser = {
    id: currentUser.username || 'unknown',  // Username statt ID!
    username: currentUser.username || 'Player',
    displayName: currentUser.username || 'Player',
    socketId: socket?.id || '',
    isOnline: true
  };

  const handleJoinSession = (sessionId: string, gameType: string) => {
    console.log(`Joining session ${sessionId} (${gameType})`);
    setCurrentSessionId(sessionId);
    setCurrentGameType(gameType);
    setCurrentView('room');
  };

  const handleLeaveRoom = () => {
    console.log('Leaving room, returning to lobby');
    setCurrentSessionId(null);
    setCurrentGameType('');
    setCurrentView('lobby');
  };

  return (
    <Container>
      <BackButton onClick={() => navigate('/games')}>
        ← Back to Games
      </BackButton>

      {currentView === 'lobby' ? (
        <GameLobby
          socket={socket}
          currentUser={gameUser}
          onJoinSession={handleJoinSession}
        />
      ) : (
        <GameRoom
          socket={socket}
          currentUser={gameUser}
          sessionId={currentSessionId!}
          onLeaveRoom={handleLeaveRoom}
        />
      )}
    </Container>
  );
};

export default MultiplayerZone;