// App.tsx - GitHub Pages Ready Version (No Backend Dependency)

import React, { useEffect, useState } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { Elements } from '@stripe/react-stripe-js';
import { loadStripe } from '@stripe/stripe-js';
import { ModeProvider } from './hooks/useModeDetection';
import RetroArcadeHome from './components/core/RetroArcadeHome';
import { RetroThemeProvider } from './shared/styles/ThemeProvider';

// User System Components
import LoginPage from './components/profilezone/login/LoginPage';

// Zone Components
import GamesZone from './components/gameszone/GamesZone';
import SingleplayerZone from './components/gameszone/singleplayer/SingleplayerZone';
import MultiplayerZone from './components/gameszone/multiplayer/MultiplayerZone';
import ArcadeZone from './components/gameszone/arcade/ArcadeZone';

// Profile & Authentication Components
import ProfileZone from './components/profilezone/ProfileZone';
import SettingsPage from './components/profilezone/settings/SettingsPage';
import RegisterPage from './components/profilezone/register/RegisterPage'; 
import PaymentPage from './components/profilezone/payment/PaymentPage';

// Payment Components
import PricingPage from './components/payment/PricingPage';
import { BillingDashboard } from './components/payment/BillingDashboard';
import PaymentSuccess from './components/payment/PaymentSuccess';

// Score & Dashboard
import ScoreView from './components/scoresview/ScoreView';
import DashboardZone from './components/dashboardzone/DashboardZone';

// Individual Games
import SnakeGame from './components/gameszone/singleplayer/SnakeGame';
import TetrisGame from './components/gameszone/singleplayer/TetrisGame';
import MemoryGame from './components/gameszone/singleplayer/MemoryGame';
import PongGame from './components/gameszone/singleplayer/PongGame';
import PongMultiplayer from './components/gameszone/multiplayer/pong/PongMultiplayer';

// SocketManager (mit Demo-Mode-Support)
import { socketManager } from './managers/SocketManager';

// Analytics (optional)
// import analytics from './utils/analytics';

const getBasename = () => {
  if (process.env.PUBLIC_URL) {
    try {
      return new URL(process.env.PUBLIC_URL).pathname;
    } catch {
      return '/legal-retro-gaming-service';
    }
  }
  return '/';
};

// Stripe initialization
const stripePromise = loadStripe(
  process.env.REACT_APP_STRIPE_PUBLISHABLE_KEY || 
  'pk_demo_mock_publishable_key_for_testing_retro_gaming'
);

// 🎭 DEMO MODE DETECTION
const IS_PRODUCTION = process.env.NODE_ENV === 'production';
const IS_GITHUB_PAGES = window.location.hostname.includes('github.io');
const DEMO_MODE = !window.location.hostname.includes('localhost') && 
                  (IS_GITHUB_PAGES || IS_PRODUCTION);

const App: React.FC = () => {
  const [socketInitialized, setSocketInitialized] = useState(false);
  const [socketStatus, setSocketStatus] = useState(socketManager.getAuthorityStatus());

  // 🎭 Demo Mode Banner
  useEffect(() => {
    if (DEMO_MODE) {
      console.log('🎭 Running in DEMO MODE (GitHub Pages)');
      console.log('📺 Backend connections are mocked');
      console.log('🎮 All UI features are visible for demonstration');
    }
  }, []);

  // Analytics initialisieren (wenn gewünscht)
  useEffect(() => {
    if (DEMO_MODE) {
      // Uncomment wenn du Analytics einbaust:
      // analytics.init('G-XXXXXXXXXX');
      // analytics.trackPageView();
    }
  }, []);

  // Socket-Initialisierung (mit Demo-Mode-Check)
  const initializeSocket = async (authData: { authority_level: string; username: string }) => {
    if (DEMO_MODE) {
      console.log('🎭 Demo Mode: Socket initialization mocked');
      setSocketInitialized(true);
      return { success: true, demo: true };
    }

    try {
      console.log('Initializing Socket.IO...');
      
      const result = await socketManager.initializeAfterLogin({
        level: authData.authority_level.toString().toUpperCase(),
        user: authData.username
      });

      if (result.success) {
        console.log('Socket.IO initialization successful');
        setSocketInitialized(true);
        setSocketStatus(socketManager.getAuthorityStatus());
      } else {
        console.error('Socket.IO initialization failed:', result.error);
      }
      
      return result;
    } catch (error) {
      console.error('Socket.IO initialization error:', error);
      return { success: false, error };
    }
  };

  // Background Socket Event Listeners
  useEffect(() => {
    if (DEMO_MODE) {
      console.log('🎭 Demo Mode: Socket listeners disabled');
      return;
    }

    console.log('Setting up background SocketManager listeners...');

    const handleStatusUpdate = () => {
      setSocketStatus(socketManager.getAuthorityStatus());
    };

    const handleAuthorityConfirmed = (data: any) => {
      console.log('Authority confirmed:', data);
      handleStatusUpdate();
    };

    const handleConnect = () => {
      console.log('SocketManager connected');
      handleStatusUpdate();
    };

    const handleDisconnect = () => {
      console.log('SocketManager disconnected');
      setSocketInitialized(false);
      handleStatusUpdate();
    };

    socketManager.on('authority-confirmed', handleAuthorityConfirmed);
    socketManager.on('connect', handleConnect);
    socketManager.on('disconnect', handleDisconnect);

    const statusInterval = setInterval(handleStatusUpdate, 30000);
    handleStatusUpdate();

    return () => {
      socketManager.off('authority-confirmed', handleAuthorityConfirmed);
      socketManager.off('connect', handleConnect);
      socketManager.off('disconnect', handleDisconnect);
      clearInterval(statusInterval);
    };
  }, []);
  
  // Socket beim App-Start verbinden (nur wenn KEIN Demo-Mode)
  useEffect(() => {
    if (DEMO_MODE) {
      console.log('🎭 Demo Mode: Skipping auth check');
      return;
    }

    const checkAuthAndConnect = async () => {
      try {
        const response = await fetch('http://localhost:3001/api/auth/authority-info', {
          credentials: 'include'
        });
        const data = await response.json();
        
        if (data.isAuthenticated && data.user) {
          console.log('User already logged in, connecting socket...');
          await initializeSocket({
            authority_level: data.authority,
            username: data.user.username
          });
        }
      } catch (error) {
        console.log('No existing session, socket will connect on login');
      }
    };
    
    checkAuthAndConnect();
  }, []);

  // Login Success Handler
  const handleLoginSuccess = async (userData: any) => {
    console.log('Login successful, initializing socket...');
    
    await initializeSocket({
      authority_level: userData.authority_level || 'DEMO',
      username: userData.username || 'anonymous'
    });
  };

  const socketFunctions = {
    initializeSocket,
    isSocketInitialized: socketInitialized,
    socketStatus,
    demoMode: DEMO_MODE
  };

  return (
    <ModeProvider>
      <RetroThemeProvider>
        <Elements stripe={stripePromise}>
          <div className="App">
            {/* 🎭 Demo Mode Banner (optional, auskommentiert) */}
            {/* {DEMO_MODE && (
              <div style={{
                position: 'fixed',
                top: 0,
                left: 0,
                right: 0,
                background: 'linear-gradient(90deg, #667eea 0%, #764ba2 100%)',
                color: 'white',
                padding: '8px',
                textAlign: 'center',
                zIndex: 9999,
                fontSize: '14px',
                fontWeight: 'bold'
              }}>
                🎭 DEMO MODE - Documentation Preview | No Backend Connection
              </div>
            )} */}

            <Router basename={getBasename()}>
              <Routes>
                {/* Main Routes */}
                <Route path="/" element={<RetroArcadeHome />} />
                <Route path="/login" element={<LoginPage />} />
                <Route path="/register" element={<RegisterPage />} />  
                
                {/* Games Zone Routes */}
                <Route path="/games" element={<GamesZone />} />
                <Route path="/singleplayer" element={<SingleplayerZone />} />
                <Route path="/multiplayer" element={<MultiplayerZone />} />
                <Route path="/arcade" element={<ArcadeZone />} />
                
                {/* Individual Games */}
                <Route path="/singleplayer/snake" element={<SnakeGame />} />
                <Route path="/singleplayer/tetris" element={<TetrisGame />} />
                <Route path="/singleplayer/memory" element={<MemoryGame />} />
                <Route path="/singleplayer/pong" element={<PongGame />} />
                {/* <Route path="/multiplayer/pong" element={<PongMultiplayer />} /> */}
                
                {/* Profile Zone Routes */}
                <Route path="/profile" element={<ProfileZone />} />
                <Route path="/settings" element={<SettingsPage />} />
                <Route path="/profile/payment" element={<PaymentPage />} />
                
                {/* Payment Routes */}
                <Route path="/pricing" element={<PricingPage />} />
                <Route path="/billing" element={<BillingDashboard />} />
                <Route path="/payment-success" element={<PaymentSuccess />} />
                
                {/* Dashboard & Scores */}
                <Route path="/dashboard" element={<DashboardZone />} />
                <Route path="/scores" element={<ScoreView />} />
              </Routes>
            </Router>
          </div>
        </Elements>
      </RetroThemeProvider>
    </ModeProvider>
  );
};

export default App;